// ============================================================================
// HPJ PHASE 90 — GRO TOGETHER / MEAL PULSE SOCIAL MVP
// ============================================================================
// A daily social layer for "What Jamaica is eating".
// Customer meal posts become an aggregated, anonymous soft demand signal for
// farmers. Meal activity never replaces confirmed buyer / wholesale demand.
// ============================================================================

class HpjMealPost {
  final String id;
  final String userId;
  final String displayName;
  final String mealName;
  final String caption;
  final String mealType;
  final String parish;
  final List<String> ingredients;
  final String imageUrl;
  final String videoUrl;
  final bool allowShop;
  final int likeCount;
  final int cookedCount;
  final int commentCount;
  final int saveCount;
  final int shareCount;
  final int creatorFollowerCount;
  final bool likedByMe;
  final bool cookedByMe;
  final bool savedByMe;
  final bool creatorFollowedByMe;
  final DateTime? createdAt;

  const HpjMealPost({
    required this.id,
    required this.userId,
    required this.displayName,
    required this.mealName,
    required this.caption,
    required this.mealType,
    required this.parish,
    required this.ingredients,
    required this.imageUrl,
    required this.videoUrl,
    required this.allowShop,
    required this.likeCount,
    required this.cookedCount,
    required this.commentCount,
    required this.saveCount,
    required this.shareCount,
    required this.creatorFollowerCount,
    required this.likedByMe,
    required this.cookedByMe,
    required this.savedByMe,
    required this.creatorFollowedByMe,
    required this.createdAt,
  });

  factory HpjMealPost.fromSupabase(Map<String, dynamic> data) {
    int number(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    bool truthy(dynamic value) {
      if (value is bool) return value;
      final clean = value?.toString().trim().toLowerCase() ?? '';
      return clean == 'true' || clean == '1' || clean == 't' || clean == 'yes';
    }

    final rawIngredients = data['ingredients'];
    final ingredients = rawIngredients is List
        ? rawIngredients
            .map((item) => item.toString().trim())
            .where((item) => item.isNotEmpty)
            .toList(growable: false)
        : <String>[];

    return HpjMealPost(
      id: (data['id'] ?? '').toString(),
      userId: (data['user_id'] ?? '').toString(),
      displayName: (data['display_name'] ?? 'HPJ Member').toString().trim(),
      mealName: (data['meal_name'] ?? 'Jamaican meal').toString().trim(),
      caption: (data['caption'] ?? '').toString().trim(),
      mealType: (data['meal_type'] ?? 'dinner').toString().trim().toLowerCase(),
      parish: (data['parish'] ?? '').toString().trim(),
      ingredients: ingredients,
      imageUrl: (data['image_url'] ?? '').toString().trim(),
      videoUrl: (data['video_url'] ?? '').toString().trim(),
      allowShop: data['allow_shop'] == null ? true : truthy(data['allow_shop']),
      likeCount: number(data['like_count']),
      cookedCount: number(data['cooked_count']),
      commentCount: number(data['comment_count']),
      saveCount: number(data['save_count']),
      shareCount: number(data['share_count']),
      creatorFollowerCount: number(data['creator_follower_count']),
      likedByMe: truthy(data['liked_by_me']),
      cookedByMe: truthy(data['cooked_by_me']),
      savedByMe: truthy(data['saved_by_me']),
      creatorFollowedByMe: truthy(data['creator_followed_by_me']),
      createdAt: parseProductDate(data['created_at']),
    );
  }

  HpjMealPost copyWith({
    int? likeCount,
    int? cookedCount,
    int? commentCount,
    int? saveCount,
    int? shareCount,
    int? creatorFollowerCount,
    bool? likedByMe,
    bool? cookedByMe,
    bool? savedByMe,
    bool? creatorFollowedByMe,
  }) {
    return HpjMealPost(
      id: id,
      userId: userId,
      displayName: displayName,
      mealName: mealName,
      caption: caption,
      mealType: mealType,
      parish: parish,
      ingredients: ingredients,
      imageUrl: imageUrl,
      videoUrl: videoUrl,
      allowShop: allowShop,
      likeCount: likeCount ?? this.likeCount,
      cookedCount: cookedCount ?? this.cookedCount,
      commentCount: commentCount ?? this.commentCount,
      saveCount: saveCount ?? this.saveCount,
      shareCount: shareCount ?? this.shareCount,
      creatorFollowerCount:
          creatorFollowerCount ?? this.creatorFollowerCount,
      likedByMe: likedByMe ?? this.likedByMe,
      cookedByMe: cookedByMe ?? this.cookedByMe,
      savedByMe: savedByMe ?? this.savedByMe,
      creatorFollowedByMe:
          creatorFollowedByMe ?? this.creatorFollowedByMe,
      createdAt: createdAt,
    );
  }
}

