class HpjMealIngredientPulse {
  final String ingredient;
  final int currentMentions;
  final int previousMentions;
  final double growthPercent;

  const HpjMealIngredientPulse({
    required this.ingredient,
    required this.currentMentions,
    required this.previousMentions,
    required this.growthPercent,
  });

  factory HpjMealIngredientPulse.fromSupabase(Map<String, dynamic> data) {
    int whole(dynamic value) {
      if (value is num) return value.toInt();
      return int.tryParse(value?.toString() ?? '') ?? 0;
    }

    double number(dynamic value) {
      if (value is num) return value.toDouble();
      return double.tryParse(value?.toString() ?? '') ?? 0;
    }

    return HpjMealIngredientPulse(
      ingredient: (data['ingredient'] ?? '').toString().trim(),
      currentMentions: whole(data['current_mentions']),
      previousMentions: whole(data['previous_mentions']),
      growthPercent: number(data['growth_percent']),
    );
  }
}

