  });
}

String _hpjMealDisplayName() {
  final user = supabase.auth.currentUser;
  if (user == null) return 'HPJ Member';

  final metadata = user.userMetadata ?? const <String, dynamic>{};

  for (final key in const <String>[
    'full_name',
    'display_name',
    'name',
  ]) {
    final value = metadata[key]?.toString().trim() ?? '';
    if (value.isNotEmpty) return value;
  }

  final first = metadata['first_name']?.toString().trim() ?? '';
  final last = metadata['last_name']?.toString().trim() ?? '';
  final combined = [first, last].where((value) => value.isNotEmpty).join(' ');
  if (combined.isNotEmpty) return combined;

  final email = user.email?.trim() ?? '';
  if (email.contains('@')) {
    final local = email.split('@').first.trim();
    if (local.isNotEmpty) return local;
  }

  return 'HPJ Member';
}

String _hpjMealRelativeTime(DateTime? value) {
  if (value == null) return 'Recently';
  final difference = DateTime.now().difference(value.toLocal());

  if (difference.inMinutes < 1) return 'Just now';
  if (difference.inMinutes < 60) return '${difference.inMinutes}m';
  if (difference.inHours < 24) return '${difference.inHours}h';
  if (difference.inDays < 7) return '${difference.inDays}d';

  return formatCustomerDateTime(value.toLocal());
}

String _hpjMealTypeLabel(String value) {
  final clean = value.trim().toLowerCase();
  switch (clean) {
    case 'breakfast':
      return 'Breakfast';
    case 'lunch':
      return 'Lunch';
    case 'snack':
      return 'Snack';
    case 'dinner':
    default:
      return 'Dinner';
  }
}

String _hpjMealDailyPrompt() {
  switch (DateTime.now().weekday) {
    case DateTime.monday:
      return 'Monday plate check — what started your week?';
    case DateTime.tuesday:
      return 'Taste of Tuesday — show Jamaica what is on your plate.';
    case DateTime.wednesday:
      return 'Midweek meal check — what did you cook today?';
    case DateTime.thursday:
      return 'Thursday table — share one meal from your day.';
    case DateTime.friday:
      return 'Friday food check — what are you eating tonight?';
    case DateTime.saturday:
      return 'Saturday kitchen — show us what is cooking.';
    case DateTime.sunday:
    default:
      return 'Sunday dinner — what is your family having today?';
  }
}

Future<List<HpjMealPost>> fetchHpjMealPulse({
  String filter = 'today',
  int limit = 40,
  int offset = 0,
}) async {
  final clean = filter.trim().toLowerCase();
  final mealType = const <String>{
    'breakfast',
    'lunch',
    'dinner',
    'snack',
  }.contains(clean)
      ? clean
      : '';

  final feedMode = clean == 'trending'
      ? 'trending'
      : clean == 'following'
          ? 'following'
          : clean == 'today'
              ? 'today'
              : 'all';

  try {
    final response = await supabase.rpc(
      'hpj_get_meal_feed',
      params: {
        'p_filter': feedMode,
        'p_meal_type': mealType,
        'p_limit': limit.clamp(1, 80),
        'p_offset': offset < 0 ? 0 : offset,
      },
    );

    return (response as List)
        .map(
          (row) => HpjMealPost.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .where((item) => item.id.isNotEmpty)
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Meal Pulse feed unavailable: $error');
    return const <HpjMealPost>[];
  }
}

Future<HpjMealPost?> fetchHpjMealPostById(String postId) async {
  final clean = postId.trim();
  if (clean.isEmpty) return null;

  try {
    final response = await supabase.rpc(
      'hpj_get_meal_post',
      params: <String, dynamic>{'p_post_id': clean},
    );
    if (response is! List || response.isEmpty) return null;
    return HpjMealPost.fromSupabase(
      Map<String, dynamic>.from(response.first as Map),
    );
  } catch (error) {
    farmDebugLog('Shared Meal Pulse post unavailable: $error');
    return null;
  }
}

Future<List<HpjMealIngredientPulse>> fetchHpjMealIngredientPulse({
  int days = 7,
  int limit = 10,
}) async {
  try {
    final response = await supabase.rpc(
      'hpj_get_meal_ingredient_pulse',
      params: {
        'p_days': days.clamp(1, 30),
        'p_limit': limit.clamp(1, 25),
      },
    );

    return (response as List)
        .map(
          (row) => HpjMealIngredientPulse.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .where((item) => item.ingredient.isNotEmpty)
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Meal ingredient pulse unavailable: $error');
    return const <HpjMealIngredientPulse>[];
  }
}

Future<HpjMealHabit> fetchHpjMealHabit() async {
  final user = supabase.auth.currentUser;
  if (user == null) {
    return const HpjMealHabit(streakDays: 0, postedToday: false);
  }

  try {
    final since = DateTime.now()
        .toUtc()
        .subtract(const Duration(days: 70))
        .toIso8601String();

    final response = await supabase
        .from('hpj_meal_posts')
        .select('created_at')
        .eq('user_id', user.id)
        .eq('is_active', true)
        .gte('created_at', since)
        .order('created_at', ascending: false);

    final dates = <String>{};
    for (final row in response as List) {
      final parsed = parseProductDate((row as Map)['created_at']);
      if (parsed == null) continue;
      final local = parsed.toLocal();
      dates.add(
        '${local.year.toString().padLeft(4, '0')}-'
        '${local.month.toString().padLeft(2, '0')}-'
        '${local.day.toString().padLeft(2, '0')}',
      );
    }

    String dayKey(DateTime value) {
      return '${value.year.toString().padLeft(4, '0')}-'
          '${value.month.toString().padLeft(2, '0')}-'
          '${value.day.toString().padLeft(2, '0')}';
    }

    final today = DateTime.now();
    final postedToday = dates.contains(dayKey(today));

    var cursor = DateTime(today.year, today.month, today.day);
    if (!postedToday) {
      cursor = cursor.subtract(const Duration(days: 1));
    }

    var streak = 0;
    while (dates.contains(dayKey(cursor))) {
      streak += 1;
      cursor = cursor.subtract(const Duration(days: 1));
    }

    return HpjMealHabit(
      streakDays: streak,
      postedToday: postedToday,
    );
  } catch (error) {
    farmDebugLog('Meal habit unavailable: $error');
    return const HpjMealHabit(streakDays: 0, postedToday: false);
  }
}

Future<String?> _hpjUploadMealPhoto() async {
  final user = supabase.auth.currentUser;
  if (user == null) {
    throw Exception('Sign in before sharing a meal.');
  }

  final picked = await pickProductImageFromDevice();
  if (picked == null) return null;

  if (picked.bytes.isEmpty) {
    throw Exception('Choose a valid meal photo.');
  }

  const maxBytes = 8 * 1024 * 1024;
  if (picked.bytes.length > maxBytes) {
    throw Exception('Meal photo must be under 8 MB.');
  }

  final mime = picked.mimeType.trim().toLowerCase();
  if (!const <String>{
    'image/jpeg',
    'image/jpg',
    'image/png',
    'image/webp',
  }.contains(mime)) {
    throw Exception('Use a JPG, PNG or WebP meal photo.');
  }

  final rawName = picked.fileName.trim().isEmpty
      ? 'meal.jpg'
      : picked.fileName.trim();

  final safeName =
      rawName.replaceAll(RegExp(r'[^A-Za-z0-9._-]+'), '-');

  final path =
      '${user.id}/${DateTime.now().millisecondsSinceEpoch}-$safeName';

  await supabase.storage.from('meal-pulse-media').uploadBinary(
        path,
        picked.bytes,
        fileOptions: FileOptions(
          contentType: mime,
          upsert: false,
        ),
      );

  return supabase.storage.from('meal-pulse-media').getPublicUrl(path);
}

Future<String?> _hpjUploadMealVideo() async {
  final user = supabase.auth.currentUser;
  if (user == null) {
    throw Exception('Sign in before sharing a meal.');
  }

  final picked = await ImagePicker().pickVideo(
    source: ImageSource.gallery,
    maxDuration: const Duration(seconds: 45),
  );
  if (picked == null) return null;

  final bytes = await picked.readAsBytes();
  if (bytes.isEmpty) {
    throw Exception('Choose a valid meal video.');
  }

  const maxBytes = 25 * 1024 * 1024;
  if (bytes.length > maxBytes) {
    throw Exception('Meal video must be under 25 MB.');
  }

  final name = picked.name.trim().isEmpty ? 'meal.mp4' : picked.name.trim();
  final safeName = name.replaceAll(RegExp(r'[^A-Za-z0-9._-]+'), '-');
  final lower = safeName.toLowerCase();
  final mime = (picked.mimeType ?? '').trim().toLowerCase();
  final contentType = mime.isNotEmpty
      ? mime
      : lower.endsWith('.mov')
          ? 'video/quicktime'
          : 'video/mp4';

  if (!const <String>{
    'video/mp4',
    'video/quicktime',
  }.contains(contentType)) {
    throw Exception('Use an MP4 or MOV meal video.');
  }

  final path =
      '${user.id}/${DateTime.now().millisecondsSinceEpoch}-$safeName';

  await supabase.storage.from('meal-pulse-media').uploadBinary(
        path,
        bytes,
        fileOptions: FileOptions(
          contentType: contentType,
          upsert: false,
        ),
      );

  return supabase.storage.from('meal-pulse-media').getPublicUrl(path);
}

Future<void> createHpjMealPost({
  required String mealName,
  required String mealType,
  required List<String> ingredients,
  String caption = '',
  String parish = '',
  String? imageUrl,
  String? videoUrl,
  bool allowShop = true,
}) async {
  final user = supabase.auth.currentUser;
  if (user == null) {
    throw Exception('Sign in before sharing a meal.');
  }

  final cleanName = mealName.trim();
  if (cleanName.isEmpty) throw Exception('Add a name for your meal.');

  final cleanIngredients = ingredients
      .map((item) => item.trim())
      .where((item) => item.isNotEmpty)
      .map((item) {
        if (item.length == 1) return item.toUpperCase();
        return '${item[0].toUpperCase()}${item.substring(1)}';
      })
      .toSet()
      .take(20)
      .toList(growable: false);

  if (cleanIngredients.isEmpty) {
    throw Exception('Add at least one ingredient.');
  }

  final cleanType = mealType.trim().toLowerCase();
  if (!const <String>{
    'breakfast',
    'lunch',
    'dinner',
    'snack',
  }.contains(cleanType)) {
    throw Exception('Choose Breakfast, Lunch, Dinner or Snack.');
  }

  final cleanImage = imageUrl?.trim() ?? '';
  final cleanVideo = videoUrl?.trim() ?? '';
  if (cleanImage.isEmpty && cleanVideo.isEmpty) {
    throw Exception('Add a meal photo or short video before sharing.');
  }

  // Phase 112 save reliability: one server-authoritative RPC now validates the
  // post, derives the signed-in identity and performs the insert. This avoids
  // browser/client RLS drift that previously produced a generic save failure.
  await supabase.rpc(
    'hpj_create_meal_post',
    params: <String, dynamic>{
      'p_meal_name': cleanName,
      'p_caption': caption.trim(),
      'p_meal_type': cleanType,
      'p_parish': parish.trim(),
      'p_ingredients': cleanIngredients,
      'p_image_url': cleanImage.isEmpty ? null : cleanImage,
      'p_video_url': cleanVideo.isEmpty ? null : cleanVideo,
      'p_allow_shop': allowShop,
    },
  );
}

Future<bool> toggleHpjMealCreatorFollow(String creatorUserId) async {
  final user = supabase.auth.currentUser;
  if (user == null) throw Exception('Sign in to follow food creators.');
  final clean = creatorUserId.trim();
  if (clean.isEmpty || clean == user.id) return false;

  final response = await supabase.rpc(
    'hpj_toggle_meal_creator_follow',
    params: <String, dynamic>{'p_creator_user_id': clean},
  );
  return response == true;
}

Future<void> recordHpjMealShare({
  required String postId,
  required String platform,
}) async {
  final cleanId = postId.trim();
  if (cleanId.isEmpty) return;
  try {
    await supabase.rpc(
      'hpj_record_meal_share',
      params: <String, dynamic>{
        'p_post_id': cleanId,
        'p_platform': platform.trim().toLowerCase(),
      },
    );
  } catch (error) {
    farmDebugLog('Meal share metric skipped: $error');
  }
}

String hpjMealShareUrl(String postId) {
  final cleanId = postId.trim();
  final raw = AppConfig.shareableAppLink.trim();
  Uri? base;

  // On the website, always share the actual website URL so an external social
  // click returns to the Meal Pulse post rather than to a mobile-store URL.
  if (kIsWeb) {
    base = Uri.base.replace(query: '', fragment: '');
  } else if (raw.startsWith('http://') || raw.startsWith('https://')) {
    base = Uri.tryParse(raw);
  }

  if (base == null) {
    return raw.isEmpty ? AppConfig.appName : raw;
  }

  final query = Map<String, String>.from(base.queryParameters);
  query['meal'] = cleanId;
  return base.replace(queryParameters: query).toString();
}


Future<bool> _hpjMealInteractionExists(
  String table,
  String postId,
) async {
  final user = supabase.auth.currentUser;
  if (user == null) return false;

  final response = await supabase
      .from(table)
      .select('post_id')
      .eq('post_id', postId)
      .eq('user_id', user.id)
      .maybeSingle();

  return response != null;
}

Future<bool> toggleHpjMealInteraction({
  required String table,
  required String postId,
}) async {
  final user = supabase.auth.currentUser;
  if (user == null) {
    throw Exception('Sign in to join the conversation.');
  }

  final exists = await _hpjMealInteractionExists(table, postId);

  if (exists) {
    await supabase
        .from(table)
        .delete()
        .eq('post_id', postId)
        .eq('user_id', user.id);
    return false;
  }

  await supabase.from(table).insert({
    'post_id': postId,
    'user_id': user.id,
  });

  return true;
}

Future<List<HpjMealComment>> fetchHpjMealComments(
  String postId,
) async {
  final cleanId = postId.trim();
  if (cleanId.isEmpty) return const <HpjMealComment>[];

  try {
    final response = await supabase
        .from('hpj_meal_post_comments')
        .select('id, post_id, user_id, display_name, body, created_at')
        .eq('post_id', cleanId)
        .order('created_at', ascending: true)
        .limit(120);

    return (response as List)
        .map(
          (row) => HpjMealComment.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Meal comments unavailable: $error');
    return const <HpjMealComment>[];
  }
}

Future<void> addHpjMealComment({
  required String postId,
  required String body,
}) async {
  final user = supabase.auth.currentUser;
  if (user == null) throw Exception('Sign in to comment.');

  final cleanBody = body.trim();
  if (cleanBody.isEmpty) return;
  if (cleanBody.length > 500) {
    throw Exception('Keep comments under 500 characters.');
  }

  await supabase.from('hpj_meal_post_comments').insert({
    'post_id': postId,
    'user_id': user.id,
    'display_name': _hpjMealDisplayName(),
    'body': cleanBody,
  });
}

Future<void> deleteHpjMealPost(String postId) async {
  final user = supabase.auth.currentUser;
  if (user == null) throw Exception('Sign in first.');

  await supabase
      .from('hpj_meal_posts')
      .update({'is_active': false})
      .eq('id', postId)
      .eq('user_id', user.id);
}

