class HpjMealPulseScreen extends StatefulWidget {
  final bool openComposerOnStart;
  final String initialPostId;

  // Native bottom-navigation mode. Standalone/web Meal Pulse keeps its
  // existing back-navigation behavior unchanged.
  final bool embeddedInNavigation;

  const HpjMealPulseScreen({
    super.key,
    this.openComposerOnStart = false,
    this.initialPostId = '',
    this.embeddedInNavigation = false,
  });

  @override
  State<HpjMealPulseScreen> createState() => _HpjMealPulseScreenState();
}

class _HpjMealPulseScreenState extends State<HpjMealPulseScreen> {
  String _filter = 'today';
  late Future<List<HpjMealPost>> _future;
  late Future<List<HpjMealIngredientPulse>> _pulseFuture;
  late Future<HpjMealHabit> _habitFuture;
  bool _composerOpened = false;

  static const _filters = <String>[
    'today',
    'following',
    'trending',
    'breakfast',
    'lunch',
    'dinner',
  ];

  @override
  void initState() {
    super.initState();
    _future = _initialMealFeed();
    _pulseFuture = fetchHpjMealIngredientPulse();
    _habitFuture = fetchHpjMealHabit();

    if (widget.openComposerOnStart) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || _composerOpened) return;
        _composerOpened = true;
        _openComposer();
      });
    }
  }

  Future<List<HpjMealPost>> _initialMealFeed() async {
    final feed = await fetchHpjMealPulse(filter: _filter);
    final postId = widget.initialPostId.trim();
    if (postId.isEmpty) return feed;

    final featured = await fetchHpjMealPostById(postId);
    if (featured == null) return feed;

    return <HpjMealPost>[
      featured,
      ...feed.where((item) => item.id != featured.id),
    ];
  }

  Future<void> _refresh() async {
    final feed = fetchHpjMealPulse(filter: _filter);
    final pulse = fetchHpjMealIngredientPulse();
    final habit = fetchHpjMealHabit();

    if (mounted) {
      setState(() {
        _future = feed;
        _pulseFuture = pulse;
        _habitFuture = habit;
      });
    }

    await Future.wait<dynamic>([feed, pulse, habit]);
  }

  void _setFilter(String value) {
    if (value == 'following' && !isLoggedIn) {
      unawaited(_openFollowingAfterLogin());
      return;
    }
    if (_filter == value) return;
    setState(() {
      _filter = value;
      _future = fetchHpjMealPulse(filter: _filter);
    });
  }

  Future<void> _openFollowingAfterLogin() async {
    if (!await _requireLogin()) return;
    if (!mounted) return;
    setState(() {
      _filter = 'following';
      _future = fetchHpjMealPulse(filter: _filter);
    });
  }

  Future<bool> _requireLogin() async {
    if (isLoggedIn) return true;

    final result = await Navigator.of(context).push<bool>(
      MaterialPageRoute<bool>(
        builder: (_) => const LoginScreen(returnToPrevious: true),
      ),
    );

    return result == true || isLoggedIn;
  }

  Future<void> _openComposer() async {
    if (!await _requireLogin()) return;
    if (!mounted) return;

    final posted = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) => const _HpjMealComposerSheet(),
    );

    if (posted == true && mounted) {
      await _refresh();
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Meal shared with Jamaica.'),
        ),
      );
    }
  }

  Future<void> _toggleReaction(
    int index, {
    required String table,
  }) async {
    if (!await _requireLogin()) return;
    if (!mounted) return;

    final posts = await _future;
    if (index < 0 || index >= posts.length) return;
    final post = posts[index];

    bool current;
    int count;

    if (table == 'hpj_meal_post_likes') {
      current = post.likedByMe;
      count = post.likeCount;
    } else if (table == 'hpj_meal_post_cooked') {
      current = post.cookedByMe;
      count = post.cookedCount;
    } else {
      current = post.savedByMe;
      count = post.saveCount;
    }

    final next = !current;
    final nextCount = next ? count + 1 : (count - 1).clamp(0, 999999).toInt();

    final updated = List<HpjMealPost>.from(posts);
    if (table == 'hpj_meal_post_likes') {
      updated[index] = post.copyWith(
        likedByMe: next,
        likeCount: nextCount,
      );
    } else if (table == 'hpj_meal_post_cooked') {
      updated[index] = post.copyWith(
        cookedByMe: next,
        cookedCount: nextCount,
      );
    } else {
      updated[index] = post.copyWith(
        savedByMe: next,
        saveCount: nextCount,
      );
    }

    setState(() {
      _future = Future<List<HpjMealPost>>.value(updated);
    });

    try {
      await toggleHpjMealInteraction(
        table: table,
        postId: post.id,
      );
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _future = Future<List<HpjMealPost>>.value(posts);
      });
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _openComments(int index) async {
    final posts = await _future;
    if (index < 0 || index >= posts.length) return;

    final before = posts[index].commentCount;
    final added = await showModalBottomSheet<int>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _HpjMealCommentsSheet(
        post: posts[index],
      ),
    );

    if (added == null || added <= 0 || !mounted) return;

    final currentPosts = await _future;
    if (index >= currentPosts.length) return;
    final updated = List<HpjMealPost>.from(currentPosts);
    updated[index] = currentPosts[index].copyWith(
      commentCount: before + added,
    );

    setState(() {
      _future = Future<List<HpjMealPost>>.value(updated);
    });
  }

  Future<void> _deleteOwnPost(int index) async {
    final posts = await _future;
    if (index < 0 || index >= posts.length) return;
    final post = posts[index];

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Remove this meal?'),
        content: const Text(
          'It will disappear from Meal Pulse and from the ingredient trend signal.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Keep'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Remove'),
          ),
        ],
      ),
    );

    if (confirmed != true) return;

    try {
      await deleteHpjMealPost(post.id);
      if (mounted) await _refresh();
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _toggleCreatorFollow(int index) async {
    if (!await _requireLogin()) return;
    if (!mounted) return;

    final posts = await _future;
    if (index < 0 || index >= posts.length) return;
    final post = posts[index];
    final currentUserId = supabase.auth.currentUser?.id ?? '';
    if (post.userId.isEmpty || post.userId == currentUserId) return;

    try {
      final following = await toggleHpjMealCreatorFollow(post.userId);
      if (!mounted) return;
      final latest = await _future;
      final updated = latest.map((item) {
        if (item.userId != post.userId) return item;
        final before = item.creatorFollowerCount;
        final nextCount = following
            ? (item.creatorFollowedByMe ? before : before + 1)
            : (item.creatorFollowedByMe ? (before - 1).clamp(0, 999999).toInt() : before);
        return item.copyWith(
          creatorFollowedByMe: following,
          creatorFollowerCount: nextCount,
        );
      }).toList(growable: false);
      setState(() {
        _future = Future<List<HpjMealPost>>.value(updated);
      });
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _shareMeal(int index) async {
    final posts = await _future;
    if (!mounted || index < 0 || index >= posts.length) return;
    await showHpjMealShareSheet(context, posts[index]);
  }

  Future<void> _openCreatorProfile(int index) async {
    final posts = await _future;
    if (!mounted || index < 0 || index >= posts.length) return;

    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => HpjMealCreatorProfileScreen(
          creatorUserId: posts[index].userId,
          fallbackDisplayName: posts[index].displayName,
        ),
      ),
    );

    if (!mounted) return;
    await _refresh();
  }

  Future<void> _saveMealToCollection(int index) async {
    if (!await _requireLogin()) return;
    final posts = await _future;
    if (!mounted || index < 0 || index >= posts.length) return;

    await showHpjMealCollectionPicker(
      context,
      posts[index],
    );
  }

  Future<void> _shopMeal(int index) async {
    final posts = await _future;
    if (!mounted || index < 0 || index >= posts.length) return;
    await showHpjShopMealSheet(context, posts[index]);
  }

  void _shopIngredient(String ingredient) {
    final clean = ingredient.trim();
    if (clean.isEmpty) return;

    mealIngredientShopSearchRequest.value = clean;
    mealIngredientReturnLabel.value = 'Meal Pulse';

    Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => const MainNavigation(initialIndex: 1),
      ),
    );
  }

  void _openFarmReels() {
    Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => HpjFreshReelsEntryScreen(
          onAddToCart: (product) {
            final cart = OfflineCartStore.restore();
            cart.add(product);
            OfflineCartStore.save(cart);

            if (isLoggedIn) {
              unawaited(saveCartItemForCurrentUser(product));
            }
          },
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final desktop = kIsWeb && MediaQuery.sizeOf(context).width >= 1000;
    final nativeMobile = hpjUseMobileAppPresentation(context);

    return Scaffold(
      backgroundColor: const Color(0xFFF7F8F3),
      appBar: AppBar(
        automaticallyImplyLeading: !widget.embeddedInNavigation,
        backgroundColor: Colors.white,
        surfaceTintColor: Colors.white,
        elevation: 0,
        titleSpacing: nativeMobile ? 16 : 18,
        title: nativeMobile
            ? const Text(
                'Meal Pulse',
                style: TextStyle(
                  color: FarmColors.deepGreen,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                  letterSpacing: -0.4,
                ),
              )
            : const Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'Meal Pulse',
                    style: TextStyle(
                      color: FarmColors.deepGreen,
                      fontWeight: FontWeight.w900,
                      letterSpacing: -0.35,
                    ),
                  ),
                  Text(
                    'What Jamaica is eating today',
                    style: TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 10,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ],
              ),
        actions: nativeMobile
            ? [
                IconButton(
                  tooltip: 'Fresh Reels',
                  onPressed: _openFarmReels,
                  icon: const Icon(Icons.smart_display_outlined),
                ),
                Padding(
                  padding: const EdgeInsets.only(right: 10),
                  child: FilledButton.icon(
                    onPressed: _openComposer,
                    icon: const Icon(Icons.add_rounded, size: 18),
                    label: const Text('Post'),
                    style: FilledButton.styleFrom(
                      backgroundColor: FarmColors.deepGreen,
                      foregroundColor: Colors.white,
                      padding: const EdgeInsets.symmetric(
                        horizontal: 12,
                        vertical: 9,
                      ),
                      minimumSize: const Size(0, 38),
                      textStyle: const TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                ),
              ]
            : [
                TextButton.icon(
                  onPressed: _openFarmReels,
                  icon: const Icon(Icons.smart_display_outlined, size: 18),
                  label: Text(desktop ? 'Farm Reels' : 'Reels'),
                ),
                const SizedBox(width: 4),
                Padding(
                  padding: const EdgeInsets.only(right: 12),
                  child: FilledButton.icon(
                    onPressed: _openComposer,
                    icon: const Icon(Icons.add_a_photo_outlined, size: 18),
                    label: const Text('Post meal'),
                  ),
                ),
              ],
      ),
      body: RefreshIndicator(
        onRefresh: _refresh,
        child: FutureBuilder<List<HpjMealPost>>(
          future: _future,
          builder: (context, snapshot) {
            final posts = snapshot.data ?? const <HpjMealPost>[];

            final feed = ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: EdgeInsets.fromLTRB(
                desktop ? 0 : 12,
                nativeMobile ? 10 : 14,
                desktop ? 0 : 12,
                120,
              ),
              children: [
                if (nativeMobile)
                  _HpjMobileMealPulseHeader(
                    habitFuture: _habitFuture,
                    onPost: _openComposer,
                  )
                else
                  _HpjMealPulseHero(
                    habitFuture: _habitFuture,
                    onPost: _openComposer,
                  ),
                SizedBox(height: nativeMobile ? 10 : 12),
                _HpjMealFilterBar(
                  filters: _filters,
                  selected: _filter,
                  onSelected: _setFilter,
                  compact: nativeMobile,
                ),
                SizedBox(height: nativeMobile ? 10 : 12),
                if (snapshot.connectionState == ConnectionState.waiting &&
                    posts.isEmpty)
                  const Padding(
                    padding: EdgeInsets.all(40),
                    child: Center(child: CircularProgressIndicator()),
                  )
                else if (posts.isEmpty)
                  _HpjMealPulseEmptyState(
                    onPost: _openComposer,
                    filter: _filter,
                  )
                else
                  ...List<Widget>.generate(
                    posts.length,
                    (index) => Padding(
                      padding: EdgeInsets.only(bottom: nativeMobile ? 10 : 12),
                      child: _HpjMealPostCard(
                        post: posts[index],
                        onLike: () => _toggleReaction(
                          index,
                          table: 'hpj_meal_post_likes',
                        ),
                        onCooked: () => _toggleReaction(
                          index,
                          table: 'hpj_meal_post_cooked',
                        ),
                        onSave: () => _toggleReaction(
                          index,
                          table: 'hpj_meal_post_saves',
                        ),
                        onComments: () => _openComments(index),
                        onCreatorProfile: () => _openCreatorProfile(index),
                        onCollection: () => _saveMealToCollection(index),
                        onFollowCreator: supabase.auth.currentUser?.id ==
                                posts[index].userId
                            ? null
                            : () => _toggleCreatorFollow(index),
                        onShare: () => _shareMeal(index),
                        onShopMeal: posts[index].allowShop
                            ? () => _shopMeal(index)
                            : null,
                        onShopIngredient: _shopIngredient,
                        onDelete: supabase.auth.currentUser?.id ==
                                posts[index].userId
                            ? () => _deleteOwnPost(index)
                            : null,
                      ),
                    ),
                  ),
              ],
            );

            if (!desktop) return feed;

            return Center(
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 1180),
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(22, 8, 22, 0),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(child: feed),
                      const SizedBox(width: 18),
                      SizedBox(
                        width: 310,
                        child: _HpjMealPulseRightRail(
                          habitFuture: _habitFuture,
                          pulseFuture: _pulseFuture,
                          onPost: _openComposer,
                          onIngredient: _shopIngredient,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        ),
      ),
    );
  }
}


