class _HpjMealVideoPlayer extends StatefulWidget {
  final String url;

  const _HpjMealVideoPlayer({required this.url});

  @override
  State<_HpjMealVideoPlayer> createState() => _HpjMealVideoPlayerState();
}

class _HpjMealVideoPlayerState extends State<_HpjMealVideoPlayer> {
  VideoPlayerController? _controller;
  bool _failed = false;

  @override
  void initState() {
    super.initState();
    final uri = Uri.tryParse(widget.url.trim());
    if (uri == null) {
      _failed = true;
      return;
    }

    final controller = VideoPlayerController.networkUrl(uri);
    _controller = controller;
    controller.initialize().then((_) {
      if (!mounted) return;
      controller.setLooping(true);
      controller.setVolume(0);
      setState(() {});
    }).catchError((_) {
      if (!mounted) return;
      setState(() => _failed = true);
    });
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = _controller;
    if (_failed) {
      return Container(
        height: 240,
        color: FarmColors.primarySoft,
        alignment: Alignment.center,
        child: const Icon(
          Icons.videocam_off_outlined,
          color: FarmColors.green,
          size: 42,
        ),
      );
    }

    if (controller == null || !controller.value.isInitialized) {
      return const AspectRatio(
        aspectRatio: 16 / 10,
        child: ColoredBox(
          color: Color(0xFF102F24),
          child: Center(
            child: CircularProgressIndicator(color: Colors.white),
          ),
        ),
      );
    }

    final ratio = controller.value.aspectRatio <= 0
        ? 16 / 10
        : controller.value.aspectRatio;

    return GestureDetector(
      onTap: () async {
        if (controller.value.isPlaying) {
          await controller.pause();
        } else {
          await controller.play();
        }
        if (mounted) setState(() {});
      },
      child: AspectRatio(
        aspectRatio: ratio,
        child: Stack(
          fit: StackFit.expand,
          children: [
            VideoPlayer(controller),
            Center(
              child: AnimatedOpacity(
                duration: const Duration(milliseconds: 160),
                opacity: controller.value.isPlaying ? 0 : 1,
                child: Container(
                  width: 58,
                  height: 58,
                  decoration: BoxDecoration(
                    color: Colors.black.withOpacity(.54),
                    shape: BoxShape.circle,
                  ),
                  child: const Icon(
                    Icons.play_arrow_rounded,
                    color: Colors.white,
                    size: 36,
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

Future<void> showHpjMealShareSheet(
  BuildContext context,
  HpjMealPost post,
) async {
  final link = hpjMealShareUrl(post.id);
  final text = '${post.mealName} on HPJ Meal Pulse 🇯🇲\n'
      '${post.caption.isEmpty ? 'See what Jamaica is cooking.' : post.caption}\n\n'
      'See the meal, join the conversation and shop the ingredients:\n$link';
  final encodedText = Uri.encodeComponent(text);
  final encodedLink = Uri.encodeComponent(link);

  Future<void> copied(String platform) async {
    await Clipboard.setData(ClipboardData(text: text));
    await recordHpjMealShare(postId: post.id, platform: platform);
  }

  Future<void> openUrl(String url, String platform) async {
    await recordHpjMealShare(postId: post.id, platform: platform);
    final opened = await openExternalShareUrl(url);
    if (!opened) {
      await Clipboard.setData(ClipboardData(text: text));
    }
  }

  Widget buildShareContent(
    BuildContext sheetContext, {
    required bool desktop,
  }) {
    Future<void> closeThen(Future<void> Function() action) async {
      Navigator.of(sheetContext).pop();
      await action();
    }

    Widget shareTile({
      required IconData icon,
      required String title,
      required String subtitle,
      required Future<void> Function() action,
    }) {
      return ListTile(
        dense: false,
        contentPadding: const EdgeInsets.symmetric(
          horizontal: 4,
          vertical: 2,
        ),
        leading: CircleAvatar(
          radius: 21,
          backgroundColor: FarmColors.primarySoft,
          foregroundColor: FarmColors.deepGreen,
          child: Icon(icon, size: 20),
        ),
        title: Text(
          title,
          style: const TextStyle(
            color: FarmColors.ink,
            fontWeight: FontWeight.w900,
          ),
        ),
        subtitle: Text(
          subtitle,
          style: const TextStyle(
            color: FarmColors.mutedText,
            fontSize: 10.5,
            fontWeight: FontWeight.w600,
          ),
        ),
        trailing: const Icon(Icons.chevron_right_rounded),
        onTap: () => closeThen(action),
      );
    }

    final content = Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (desktop)
          Row(
            children: [
              const Expanded(
                child: Text(
                  'Share this meal',
                  style: TextStyle(
                    color: FarmColors.deepGreen,
                    fontSize: 20,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              IconButton(
                tooltip: 'Close',
                onPressed: () => Navigator.of(sheetContext).pop(),
                icon: const Icon(Icons.close_rounded),
              ),
            ],
          )
        else
          const Text(
            'Share this meal',
            style: TextStyle(
              color: FarmColors.deepGreen,
              fontSize: 20,
              fontWeight: FontWeight.w900,
            ),
          ),
        const SizedBox(height: 4),
        const Text(
          'Bring people back to HPJ to like, comment, follow creators and shop the ingredients.',
          style: TextStyle(
            color: FarmColors.mutedText,
            fontSize: 10,
            height: 1.35,
            fontWeight: FontWeight.w600,
          ),
        ),
        const SizedBox(height: 8),
        shareTile(
          icon: Icons.facebook,
          title: 'Facebook',
          subtitle: 'Share the HPJ meal link',
          action: () => openUrl(
            'https://www.facebook.com/sharer/sharer.php?u=$encodedLink',
            'facebook',
          ),
        ),
        shareTile(
          icon: Icons.chat_bubble_outline_rounded,
          title: 'WhatsApp',
          subtitle: 'Send to chats or groups',
          action: () => openUrl(
            'https://wa.me/?text=$encodedText',
            'whatsapp',
          ),
        ),
        shareTile(
          icon: Icons.camera_alt_outlined,
          title: 'Instagram',
          subtitle: 'Copy the link, then open Instagram',
          action: () async {
            await copied('instagram');
            await openExternalShareUrl('https://www.instagram.com/');
          },
        ),
        shareTile(
          icon: Icons.music_note_rounded,
          title: 'TikTok',
          subtitle: 'Copy the link, then open TikTok',
          action: () async {
            await copied('tiktok');
            await openExternalShareUrl('https://www.tiktok.com/');
          },
        ),
        shareTile(
          icon: Icons.link_rounded,
          title: 'Copy link',
          subtitle: 'Share anywhere',
          action: () => copied('copy'),
        ),
      ],
    );

    return SingleChildScrollView(
      physics: const ClampingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(
        desktop ? 20 : 18,
        desktop ? 18 : 2,
        desktop ? 20 : 18,
        desktop ? 18 : 28,
      ),
      child: content,
    );
  }

  if (!context.mounted) return;

  final isDesktop =
      MediaQuery.sizeOf(context).width >= 720;

  if (isDesktop) {
    await showDialog<void>(
      context: context,
      builder: (dialogContext) {
        final screen = MediaQuery.sizeOf(dialogContext);
        return Dialog(
          insetPadding: const EdgeInsets.all(24),
          backgroundColor: Colors.white,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(24),
          ),
          child: ConstrainedBox(
            constraints: BoxConstraints(
              maxWidth: 520,
              maxHeight: screen.height * .82,
            ),
            child: buildShareContent(
              dialogContext,
              desktop: true,
            ),
          ),
        );
      },
    );
    return;
  }

  await showModalBottomSheet<void>(
    context: context,
    useSafeArea: true,
    isScrollControlled: true,
    showDragHandle: true,
    backgroundColor: Colors.white,
    builder: (sheetContext) {
      final screen = MediaQuery.sizeOf(sheetContext);
      return ConstrainedBox(
        constraints: BoxConstraints(
          maxHeight: screen.height * .88,
        ),
        child: buildShareContent(
          sheetContext,
          desktop: false,
        ),
      );
    },
  );
}

String _hpjMealIngredientKey(String value) {
  return value
      .trim()
      .toLowerCase()
      .replaceAll('&', 'and')
      .replaceAll(RegExp(r'[^a-z0-9]+'), ' ')
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim();
}

Product? _hpjMealIngredientProduct(
  String ingredient,
  Iterable<Product> products,
) {
  final key = _hpjMealIngredientKey(ingredient);
  if (key.isEmpty) return null;

  Product? partial;
  for (final product in products) {
    final productKey = _hpjMealIngredientKey(product.name);
    if (productKey == key) return product;
    if (partial == null &&
        (productKey.contains(key) || key.contains(productKey))) {
      partial = product;
    }
  }
  return partial;
}

