class _HpjShopMealSheet extends StatefulWidget {
  final HpjMealPost post;

  const _HpjShopMealSheet({required this.post});

  @override
  State<_HpjShopMealSheet> createState() => _HpjShopMealSheetState();
}

class _HpjShopMealSheetState extends State<_HpjShopMealSheet> {
  late Future<List<Product>> _productsFuture;
  bool addingAll = false;

  @override
  void initState() {
    super.initState();
    _productsFuture = fetchProductsForCustomerUi(
      forceRefresh: false,
      timeout: const Duration(seconds: 8),
    );
  }

  Future<void> _addProduct(Product product) async {
    if (!product.canAddToCart) return;
    final cart = OfflineCartStore.restore();
    cart.add(product);
    OfflineCartStore.save(cart);
    if (isLoggedIn) {
      await saveCartItemForCurrentUser(product);
    }
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('${product.name} added to My Box.')),
    );
  }

  Future<void> _addAll(List<Product> products) async {
    if (addingAll) return;
    setState(() => addingAll = true);
    try {
      final matches = <Product>[];
      final seen = <String>{};
      for (final ingredient in widget.post.ingredients) {
        final product = _hpjMealIngredientProduct(ingredient, products);
        if (product == null || !product.canAddToCart) continue;
        if (seen.add(product.id)) matches.add(product);
      }

      if (matches.isEmpty) {
        throw Exception('No ingredients from this meal are available to add right now.');
      }

      final cart = OfflineCartStore.restore();
      for (final product in matches) {
        cart.add(product);
      }
      OfflineCartStore.save(cart);

      if (isLoggedIn) {
        for (final product in matches) {
          await saveCartItemForCurrentUser(product);
        }
      }

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${matches.length} ingredient${matches.length == 1 ? '' : 's'} added to My Box.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    } finally {
      if (mounted) setState(() => addingAll = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final height = MediaQuery.sizeOf(context).height * .82;
    return SizedBox(
      height: height,
      child: FutureBuilder<List<Product>>(
        future: _productsFuture,
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting &&
              snapshot.data == null) {
            return const Center(child: CircularProgressIndicator());
          }

          final products = snapshot.data ?? const <Product>[];
          final availableMatches = widget.post.ingredients
              .map((ingredient) => _hpjMealIngredientProduct(ingredient, products))
              .whereType<Product>()
              .where((product) => product.canAddToCart)
              .map((product) => product.id)
              .toSet()
              .length;

          return Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(18, 4, 18, 12),
                child: Row(
                  children: [
                    const Icon(
                      Icons.shopping_basket_outlined,
                      color: FarmColors.deepGreen,
                    ),
                    const SizedBox(width: 9),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'Shop ${widget.post.mealName}',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: FarmColors.deepGreen,
                              fontSize: 18,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          Text(
                            '$availableMatches ingredient${availableMatches == 1 ? '' : 's'} available through HPJ now.',
                            style: const TextStyle(
                              color: FarmColors.mutedText,
                              fontSize: 9.5,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ],
                      ),
                    ),
                    FilledButton.icon(
                      onPressed: addingAll || availableMatches == 0
                          ? null
                          : () => _addAll(products),
                      icon: const Icon(Icons.add_shopping_cart_rounded, size: 16),
                      label: Text(addingAll ? 'Adding…' : 'Add available'),
                    ),
                  ],
                ),
              ),
              const Divider(height: 1),
              Expanded(
                child: ListView.separated(
                  padding: const EdgeInsets.all(16),
                  itemCount: widget.post.ingredients.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 8),
                  itemBuilder: (context, index) {
                    final ingredient = widget.post.ingredients[index];
                    final product = _hpjMealIngredientProduct(
                      ingredient,
                      products,
                    );
                    final available = product?.canAddToCart == true;

                    return Container(
                      padding: const EdgeInsets.all(11),
                      decoration: BoxDecoration(
                        color: const Color(0xFFF7FAF5),
                        borderRadius: BorderRadius.circular(15),
                        border: Border.all(color: FarmColors.line),
                      ),
                      child: Row(
                        children: [
                          Container(
                            width: 42,
                            height: 42,
                            alignment: Alignment.center,
                            decoration: BoxDecoration(
                              color: available
                                  ? FarmColors.primarySoft
                                  : Colors.white,
                              borderRadius: BorderRadius.circular(12),
                            ),
                            child: Icon(
                              available
                                  ? Icons.eco_rounded
                                  : Icons.kitchen_outlined,
                              color: available
                                  ? FarmColors.green
                                  : FarmColors.mutedText,
                            ),
                          ),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  ingredient,
                                  style: const TextStyle(
                                    color: FarmColors.ink,
                                    fontSize: 11.5,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                                const SizedBox(height: 2),
                                Text(
                                  product == null
                                      ? 'Pantry/community ingredient'
                                      : available
                                          ? '${product.name} • ${product.formattedPrice}'
                                          : '${product.name} • not available right now',
                                  style: const TextStyle(
                                    color: FarmColors.mutedText,
                                    fontSize: 8.8,
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          if (product != null)
                            TextButton(
                              onPressed: available
                                  ? () => _addProduct(product)
                                  : null,
                              child: Text(available ? 'Add' : 'Unavailable'),
                            ),
                        ],
                      ),
                    );
                  },
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

String _hpjMealPulseErrorMessage(Object error) {
  final raw = error.toString().trim();
  final lower = raw.toLowerCase();

  if (lower.contains('hpj_create_meal_post') &&
      (lower.contains('not found') ||
          lower.contains('pgrst202') ||
          lower.contains('could not find'))) {
    return 'Meal Pulse database update is not installed yet. Run the Meal Pulse MASTER REPAIR SQL, refresh HPJ, then try again.';
  }

  if (lower.contains('display_name') &&
      (lower.contains('does not exist') ||
          lower.contains('column'))) {
    return 'Meal Pulse is still using an older database schema. Run the Meal Pulse MASTER REPAIR SQL, then refresh HPJ.';
  }

  if (lower.contains('meal-pulse-media') ||
      (lower.contains('storage') && lower.contains('bucket'))) {
    return 'Meal photo/video storage is not ready yet. Run the Meal Pulse MASTER REPAIR SQL and try again.';
  }

  if (lower.contains('row level security') ||
      lower.contains('42501') ||
      lower.contains('permission denied')) {
    return 'Meal Pulse permissions need to be refreshed. Run the Meal Pulse MASTER REPAIR SQL, then sign out and back in.';
  }

  if (lower.contains('jwt') ||
      lower.contains('session') ||
      lower.contains('not authenticated')) {
    return 'Your session needs to be refreshed. Please sign in again.';
  }

  var clean = raw
      .replaceFirst(RegExp(r'^Exception:\s*', caseSensitive: false), '')
      .replaceFirst(RegExp(r'^PostgrestException\(message:\s*', caseSensitive: false), '');

  final commaCode = clean.indexOf(', code:');
  if (commaCode > 0) clean = clean.substring(0, commaCode);

  clean = clean.replaceAll(RegExp(r'\)$'), '').trim();

  if (clean.isNotEmpty && clean.length <= 220) return clean;

  return 'Meal Pulse could not save this post. Run the MASTER REPAIR SQL, refresh HPJ and try again.';
}

class _HpjMealComposerSheet extends StatefulWidget {
  const _HpjMealComposerSheet();

  @override
  State<_HpjMealComposerSheet> createState() => _HpjMealComposerSheetState();
}

class _HpjMealComposerSheetState extends State<_HpjMealComposerSheet> {
  final mealNameController = TextEditingController();
  final captionController = TextEditingController();
  final parishController = TextEditingController();
  final customIngredientController = TextEditingController();

  String mealType = 'dinner';
  String? imageUrl;
  String? videoUrl;
  bool allowShop = true;
  bool uploading = false;
  bool saving = false;

  final Set<String> selectedIngredients = <String>{};

  static const suggestions = <String>[
    'Callaloo',
    'Scotch Bonnet',
    'Thyme',
    'Tomato',
    'Onion',
    'Sweet Pepper',
    'Pumpkin',
    'Yam',
    'Green Banana',
    'Plantain',
    'Sweet Potato',
    'Cabbage',
    'Carrot',
    'Okra',
    'Cucumber',
    'Ackee',
  ];

  @override
  void dispose() {
    mealNameController.dispose();
    captionController.dispose();
    parishController.dispose();
    customIngredientController.dispose();
    super.dispose();
  }

  Future<void> _choosePhoto() async {
    setState(() => uploading = true);
    try {
      final uploaded = await _hpjUploadMealPhoto();
      if (!mounted) return;
      if (uploaded != null) {
        setState(() {
          imageUrl = uploaded;
          videoUrl = null;
        });
      }
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(_hpjMealPulseErrorMessage(error))),
      );
    } finally {
      if (mounted) setState(() => uploading = false);
    }
  }

  Future<void> _chooseVideo() async {
    setState(() => uploading = true);
    try {
      final uploaded = await _hpjUploadMealVideo();
      if (!mounted) return;
      if (uploaded != null) {
        setState(() {
          videoUrl = uploaded;
          imageUrl = null;
        });
      }
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(_hpjMealPulseErrorMessage(error))),
      );
    } finally {
      if (mounted) setState(() => uploading = false);
    }
  }

  void _addCustomIngredient() {
    final values = customIngredientController.text
        .split(RegExp(r'[,\n]'))
        .map((value) => value.trim())
        .where((value) => value.isNotEmpty);

    setState(() {
      selectedIngredients.addAll(values);
      customIngredientController.clear();
    });
  }

  void _showPublishMessage(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  Future<void> _publish() async {
    if (saving || uploading) return;

    _addCustomIngredient();

    final cleanName = mealNameController.text.trim();
    final hasPhoto = imageUrl?.trim().isNotEmpty == true;
    final hasVideo = videoUrl?.trim().isNotEmpty == true;

    if (cleanName.isEmpty) {
      _showPublishMessage('Add a name for your meal first.');
      return;
    }

    if (!hasPhoto && !hasVideo) {
      _showPublishMessage('Add a meal photo or short video before sharing.');
      return;
    }

    if (selectedIngredients.isEmpty) {
      _showPublishMessage('Tag at least one ingredient before sharing.');
      return;
    }

    setState(() => saving = true);

    try {
      await createHpjMealPost(
        mealName: cleanName,
        mealType: mealType,
        ingredients: selectedIngredients.toList(),
        caption: captionController.text,
        parish: parishController.text,
        imageUrl: imageUrl,
        videoUrl: videoUrl,
        allowShop: allowShop,
      );

      if (!mounted) return;
      Navigator.of(context).pop(true);
    } catch (error) {
      farmDebugLog('Meal Pulse publish failed: $error');
      if (!mounted) return;
      _showPublishMessage(_hpjMealPulseErrorMessage(error));
    } finally {
      if (mounted) setState(() => saving = false);
    }
  }

