class _HpjMealCommentsSheet extends StatefulWidget {
  final HpjMealPost post;

  const _HpjMealCommentsSheet({
    required this.post,
  });

  @override
  State<_HpjMealCommentsSheet> createState() =>
      _HpjMealCommentsSheetState();
}

class _HpjMealCommentsSheetState extends State<_HpjMealCommentsSheet> {
  final controller = TextEditingController();
  late Future<List<HpjMealComment>> _future;
  int addedCount = 0;
  bool sending = false;

  @override
  void initState() {
    super.initState();
    _future = fetchHpjMealComments(widget.post.id);
  }

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  Future<void> _send() async {
    if (sending || controller.text.trim().isEmpty) return;

    if (!isLoggedIn) {
      final result = await Navigator.of(context).push<bool>(
        MaterialPageRoute<bool>(
          builder: (_) => const LoginScreen(returnToPrevious: true),
        ),
      );
      if (result != true && !isLoggedIn) return;
    }

    setState(() => sending = true);
    try {
      await addHpjMealComment(
        postId: widget.post.id,
        body: controller.text,
      );
      controller.clear();
      addedCount += 1;
      if (!mounted) return;
      setState(() {
        _future = fetchHpjMealComments(widget.post.id);
      });
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    } finally {
      if (mounted) setState(() => sending = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final bottom = MediaQuery.viewInsetsOf(context).bottom;

    return Container(
      height: MediaQuery.sizeOf(context).height * .78,
      padding: EdgeInsets.fromLTRB(16, 16, 16, 12 + bottom),
      decoration: const BoxDecoration(
        color: Color(0xFFF9FAF6),
        borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
      ),
      child: Column(
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  'Comments • ${widget.post.mealName}',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: FarmColors.deepGreen,
                    fontSize: 17,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              IconButton(
                onPressed: () => Navigator.pop(context, addedCount),
                icon: const Icon(Icons.close_rounded),
              ),
            ],
          ),
          const Divider(),
          Expanded(
            child: FutureBuilder<List<HpjMealComment>>(
              future: _future,
              builder: (context, snapshot) {
                final comments =
                    snapshot.data ?? const <HpjMealComment>[];

                if (snapshot.connectionState == ConnectionState.waiting &&
                    comments.isEmpty) {
                  return const Center(child: CircularProgressIndicator());
                }

                if (comments.isEmpty) {
                  return const Center(
                    child: Text(
                      'Be the first to join the conversation.',
                      style: TextStyle(
                        color: FarmColors.mutedText,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  );
                }

                return ListView.separated(
                  padding: const EdgeInsets.symmetric(vertical: 8),
                  itemCount: comments.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 8),
                  itemBuilder: (context, index) {
                    final comment = comments[index];
                    final initial = comment.displayName.isEmpty
                        ? 'H'
                        : comment.displayName[0].toUpperCase();

                    return Container(
                      padding: const EdgeInsets.all(11),
                      decoration: BoxDecoration(
                        color: Colors.white,
                        borderRadius: BorderRadius.circular(16),
                        border: Border.all(color: FarmColors.line),
                      ),
                      child: Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          CircleAvatar(
                            radius: 16,
                            backgroundColor: FarmColors.primarySoft,
                            child: Text(
                              initial,
                              style: const TextStyle(
                                color: FarmColors.green,
                                fontSize: 11,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          ),
                          const SizedBox(width: 9),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Row(
                                  children: [
                                    Expanded(
                                      child: Text(
                                        comment.displayName,
                                        style: const TextStyle(
                                          color: FarmColors.deepGreen,
                                          fontSize: 10.5,
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                    ),
                                    Text(
                                      _hpjMealRelativeTime(
                                        comment.createdAt,
                                      ),
                                      style: const TextStyle(
                                        color: FarmColors.mutedText,
                                        fontSize: 8.5,
                                        fontWeight: FontWeight.w700,
                                      ),
                                    ),
                                  ],
                                ),
                                const SizedBox(height: 4),
                                Text(
                                  comment.body,
                                  style: const TextStyle(
                                    color: FarmColors.ink,
                                    height: 1.4,
                                    fontSize: 10.5,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    );
                  },
                );
              },
            ),
          ),
          const SizedBox(height: 8),
          Row(
            children: [
              Expanded(
                child: TextField(
                  controller: controller,
                  maxLength: 500,
                  maxLines: 2,
                  minLines: 1,
                  decoration: const InputDecoration(
                    hintText: 'Add a comment...',
                    counterText: '',
                  ),
                  onSubmitted: (_) => _send(),
                ),
              ),
              const SizedBox(width: 8),
              IconButton.filled(
                onPressed: sending ? null : _send,
                icon: sending
                    ? const SizedBox(
                        width: 17,
                        height: 17,
                        child: CircularProgressIndicator(
                          strokeWidth: 2,
                          color: Colors.white,
                        ),
                      )
                    : const Icon(Icons.send_rounded),
              ),
            ],
          ),
        ],
      ),
    );
  }
}


List<HomeHeroSlide> defaultHomeHeroSlides() {
  return List<HomeHeroSlide>.generate(_defaultHomeHeroImageUrls.length,
      (index) {
    return HomeHeroSlide(
      id: 'default-${index + 1}',
      position: index + 1,
      imageUrl: _defaultHomeHeroImageUrls[index],
      isActive: true,
    );
  });
}

List<HomeHeroSlide> _cleanHomeHeroSlides(List<HomeHeroSlide> slides) {
  final clean = slides
      .where((slide) => cleanHostedImageUrl(slide.imageUrl) != null)
      .toList()
    ..sort((a, b) => a.position.compareTo(b.position));

  if (clean.isEmpty) return defaultHomeHeroSlides();
  return clean.take(4).toList();
}

