class HpjHarvestCirclesScreen extends StatefulWidget {
  const HpjHarvestCirclesScreen({super.key});

  @override
  State<HpjHarvestCirclesScreen> createState() =>
      _HpjHarvestCirclesScreenState();
}

class _HpjHarvestCirclesScreenState extends State<HpjHarvestCirclesScreen> {
  String _filter = 'all';
  late Future<List<HpjHarvestCircle>> _future;

  @override
  void initState() {
    super.initState();
    _future = fetchHpjHarvestCircles();
  }

  Future<void> _refresh() async {
    final next = fetchHpjHarvestCircles();
    if (mounted) setState(() => _future = next);
    await next;
  }

  Future<bool> _requireLogin() async {
    if (isLoggedIn) return true;
    final result = await Navigator.of(context).push<bool>(
      MaterialPageRoute<bool>(
        builder: (_) => const LoginScreen(returnToPrevious: true),
      ),
    );
    return result == true || isLoggedIn;
  }

  List<HpjHarvestCircle> _filtered(List<HpjHarvestCircle> source) {
    switch (_filter) {
      case 'mine':
        return source
            .where((circle) => circle.myCommitmentType.isNotEmpty)
            .toList(growable: false);
      case 'nearly_ready':
        return source
            .where((circle) => circle.demandProgress >= .65)
            .toList(growable: false);
      case 'growing':
        return source
            .where(
              (circle) =>
                  circle.status == 'growing' || circle.status == 'harvesting',
            )
            .toList(growable: false);
      default:
        return source;
    }
  }

  Future<void> _follow(HpjHarvestCircle circle) async {
    if (!await _requireLogin()) return;
    if (!mounted) return;

    // A reservation/repeat already means the customer is following this
    // harvest. Never downgrade a live reservation to a zero-quantity
    // "follow" commitment.
    if (circle.isReserved) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Your ${circle.productName} reservation already follows this harvest.',
          ),
        ),
      );
      return;
    }

    try {
      await saveHpjHarvestCircleCommitment(
        circleId: circle.id,
        commitmentType: 'follow',
      );
      if (!mounted) return;
      await _refresh();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Following ${circle.productName} harvest.')),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _reserve(HpjHarvestCircle circle) async {
    if (!await _requireLogin()) return;
    if (!mounted) return;

    final changed = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _HpjHarvestCommitmentSheet(circle: circle),
    );

    if (changed == true && mounted) await _refresh();
  }

  Future<void> _remove(HpjHarvestCircle circle) async {
    if (!await _requireLogin()) return;

    try {
      if (circle.isReserved) {
        // Removing the reservation keeps the customer connected to the
        // harvest instead of deleting the relationship completely.
        await saveHpjHarvestCircleCommitment(
          circleId: circle.id,
          commitmentType: 'follow',
          quantity: 0,
          repeatWeeks: 1,
        );
      } else {
        await cancelHpjHarvestCircleCommitment(circle.id);
      }

      if (!mounted) return;
      await _refresh();
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            circle.isReserved
                ? 'Reservation removed. You’re still following ${circle.productName}.'
                : 'You’re no longer following ${circle.productName}.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _openJourney(HpjHarvestCircle circle) async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => HpjHarvestJourneyScreen(circle: circle),
      ),
    );
    if (mounted) await _refresh();
  }

  @override
  Widget build(BuildContext context) {
    final desktop = kIsWeb && MediaQuery.sizeOf(context).width >= 1000;

    return Scaffold(
      backgroundColor: const Color(0xFFF6F8F2),
      appBar: AppBar(
        backgroundColor: Colors.white,
        surfaceTintColor: Colors.white,
        title: const Text(
          'GrowTogether',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
      ),
      body: RefreshIndicator(
        onRefresh: _refresh,
        child: FutureBuilder<List<HpjHarvestCircle>>(
          future: _future,
          builder: (context, snapshot) {
            final all = snapshot.data ?? const <HpjHarvestCircle>[];
            final circles = _filtered(all);

            return ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: EdgeInsets.fromLTRB(
                desktop ? 34 : 16,
                desktop ? 28 : 16,
                desktop ? 34 : 16,
                48,
              ),
              children: [
                Center(
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 1240),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        if (!kIsWeb)
                          _HpjMobileGrowTogetherHeader(
                            circleCount: all.length,
                            reservationCount: all.fold<int>(
                              0,
                              (sum, item) => sum + item.householdCount,
                            ),
                          )
                        else
                          _HpjGrowTogetherHero(
                            circleCount: all.length,
                            reservationCount: all.fold<int>(
                              0,
                              (sum, item) => sum + item.householdCount,
                            ),
                          ),
                        SizedBox(height: kIsWeb ? 14 : 10),
                        if (!kIsWeb)
                          const HpjHarvestDropPreview(compact: true)
                        else
                          const HpjHarvestDropPreview(),
                        SizedBox(height: kIsWeb ? 14 : 10),
                        if (!kIsWeb)
                          const HpjRescueHarvestPreview(compact: true)
                        else
                          const HpjRescueHarvestPreview(),
                        SizedBox(height: kIsWeb ? 18 : 14),
                        SingleChildScrollView(
                          scrollDirection: Axis.horizontal,
                          child: Row(
                            children: [
                              _filterChip('all', 'All circles'),
                              const SizedBox(width: 8),
                              _filterChip('nearly_ready', 'Needs a final push'),
                              const SizedBox(width: 8),
                              _filterChip('growing', 'Growing now'),
                              const SizedBox(width: 8),
                              _filterChip('mine', 'Following'),
                            ],
                          ),
                        ),
                        const SizedBox(height: 16),
                        if (snapshot.connectionState == ConnectionState.waiting &&
                            all.isEmpty)
                          const SizedBox(
                            height: 280,
                            child: Center(child: CircularProgressIndicator()),
                          )
                        else if (circles.isEmpty)
                          _emptyState(all.isEmpty)
                        else
                          LayoutBuilder(
                            builder: (context, constraints) {
                              final columns = constraints.maxWidth >= 1080
                                  ? 3
                                  : constraints.maxWidth >= 690
                                      ? 2
                                      : 1;
                              final gap = 14.0;
                              final width = columns == 1
                                  ? constraints.maxWidth
                                  : (constraints.maxWidth - gap * (columns - 1)) /
                                      columns;

                              return Wrap(
                                spacing: gap,
                                runSpacing: gap,
                                children: circles
                                    .map(
                                      (circle) => SizedBox(
                                        width: width,
                                        child: _HpjHarvestCircleCard(
                                          circle: circle,
                                          onFollow: () => _follow(circle),
                                          onReserve: () => _reserve(circle),
                                          onRemove: () => _remove(circle),
                                          onJourney: () => _openJourney(circle),
                                        ),
                                      ),
                                    )
                                    .toList(growable: false),
                              );
                            },
                          ),
                      ],
                    ),
                  ),
                ),
              ],
            );
          },
        ),
      ),
    );
  }

  Widget _filterChip(String value, String label) {
    final selected = _filter == value;
    return ChoiceChip(
      label: Text(label),
      selected: selected,
      onSelected: (_) => setState(() => _filter = value),
      selectedColor: const Color(0xFF0C4B36),
      backgroundColor: Colors.white,
      side: const BorderSide(color: Color(0xFFDCE5DA)),
      labelStyle: TextStyle(
        color: selected ? Colors.white : const Color(0xFF315846),
        fontWeight: FontWeight.w800,
        fontSize: 11,
      ),
    );
  }

  Widget _emptyState(bool noCirclesAtAll) {
    return Container(
      padding: const EdgeInsets.all(28),
      decoration: BoxDecoration(
        color: Colors.white,
