class _HpjHarvestDropPreviewState extends State<HpjHarvestDropPreview> {
  late Future<List<HpjHarvestDrop>> _future;

  @override
  void initState() {
    super.initState();
    _future = fetchMyHpjHarvestDrops(limit: widget.compact ? 8 : 16);
  }

  Future<void> _refresh() async {
    final next = fetchMyHpjHarvestDrops(limit: widget.compact ? 8 : 16);
    if (mounted) setState(() => _future = next);
    await next;
  }

  Future<void> _action(HpjHarvestDrop item) async {
    if (item.isOrdered) {
      await _hpjOpenHarvestDropOrder(context, item);
      if (mounted) await _refresh();
      return;
    }

    await _hpjMoveHarvestDropToMyBox(context, item);
    if (mounted) await _refresh();
  }

  @override
  Widget build(BuildContext context) {
    if (!isLoggedIn) return const SizedBox.shrink();

    return FutureBuilder<List<HpjHarvestDrop>>(
      future: _future,
      builder: (context, snapshot) {
        final all = snapshot.data ?? const <HpjHarvestDrop>[];
        final items = all
            .where(
              (item) =>
                  item.dropStatus != 'waiting' ||
                  item.isClaimed ||
                  item.isOrdered,
            )
            .take(widget.compact ? 3 : 5)
            .toList(growable: false);

        if (snapshot.connectionState == ConnectionState.waiting &&
            items.isEmpty) {
          return const SizedBox.shrink();
        }
        if (items.isEmpty) return const SizedBox.shrink();

        return Container(
          width: double.infinity,
          padding: EdgeInsets.all(widget.compact ? 16 : 19),
          decoration: BoxDecoration(
            gradient: const LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: [
                Color(0xFF073F2C),
                Color(0xFF0F6042),
              ],
            ),
            borderRadius: BorderRadius.circular(widget.compact ? 23 : 28),
            boxShadow: [
              BoxShadow(
                color: const Color(0xFF073F2C).withOpacity(.14),
                blurRadius: 28,
                offset: const Offset(0, 11),
              ),
            ],
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Container(
                    width: 42,
                    height: 42,
                    decoration: BoxDecoration(
                      color: Colors.white.withOpacity(.10),
                      borderRadius: BorderRadius.circular(14),
                      border: Border.all(color: Colors.white.withOpacity(.10)),
                    ),
                    child: const Icon(
                      Icons.inventory_2_outlined,
                      color: Color(0xFFFFD45A),
                      size: 21,
                    ),
                  ),
                  const SizedBox(width: 11),
                  const Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Your Harvest Drops',
                          style: TextStyle(
                            color: Colors.white,
                            fontSize: 17,
                            fontWeight: FontWeight.w900,
                            letterSpacing: -.25,
                          ),
                        ),
                        SizedBox(height: 2),
                        Text(
                          'When your reserved harvest is ready, move it into the real HPJ checkout.',
                          style: TextStyle(
                            color: Color(0xFFC8DED4),
                            fontSize: 9.7,
                            height: 1.35,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 13),
              ...items.map(
                (item) => Padding(
                  padding: const EdgeInsets.only(bottom: 8),
                  child: _HpjHarvestDropRow(
