class _HpjHarvestDropOrderTimeline extends StatelessWidget {
  final HpjHarvestDrop item;
  final int progress;

  const _HpjHarvestDropOrderTimeline({
    required this.item,
    required this.progress,
  });

  @override
  Widget build(BuildContext context) {
    final steps = <String>[
      'Order placed',
      'Preparing & packing',
      item.fulfillmentType == 'pickup' ? 'Ready for pickup' : 'Ready for dispatch',
      item.fulfillmentType == 'pickup' ? 'Pickup handoff' : 'Out for delivery',
      item.fulfillmentType == 'pickup' ? 'Collected' : 'Delivered',
    ];

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: const Color(0xFFF6F8F4),
        borderRadius: BorderRadius.circular(16),
      ),
      child: Wrap(
        spacing: 6,
        runSpacing: 6,
        children: List<Widget>.generate(steps.length, (index) {
          final done = progress >= index + 1;
          return Container(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
            decoration: BoxDecoration(
              color: done ? const Color(0xFFE4F4EA) : Colors.white,
              borderRadius: BorderRadius.circular(999),
              border: Border.all(
                color: done
                    ? const Color(0xFFB8DEC7)
                    : const Color(0xFFDDE4DF),
