              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(
                  done ? Icons.check_circle_rounded : Icons.circle_outlined,
                  size: 12,
                  color: done
                      ? const Color(0xFF168A58)
                      : const Color(0xFF9AA49F),
                ),
                const SizedBox(width: 4),
                Text(
                  steps[index],
                  style: TextStyle(
                    color: done
                        ? const Color(0xFF225D42)
                        : const Color(0xFF78847D),
                    fontSize: 7.8,
                    fontWeight: FontWeight.w800,
                  ),
                ),
              ],
            ),
          );
        }),
      ),
    );
  }
}



// ============================================================================
// HPJ PHASE 94 — FARM-TO-BOX PASSPORT
//
// Trust-first provenance for GrowTogether / Harvest Drop orders.
//
// HPJ shows only relationships the database can actually prove:
//   Harvest Drop order -> Harvest Circle -> participating farmer supply
//   -> field update -> HPJ-confirmed supply -> associated receiving record.
//
// An associated receiving batch is NOT described as the exact packed lot unless
// HPJ has an explicit packed-lot link. This keeps customer trust stronger than
// a marketing claim the operational data cannot yet prove.
// ============================================================================

class HpjFarmPassportSource {
  final String snapshotId;
  final String sourceKey;
  final String orderId;
  final String circleId;
  final String productId;
  final String productName;
  final String imageUrl;
  final String unit;
  final double reservedQuantity;
  final double orderedQuantity;
  final DateTime? harvestStart;
  final DateTime? harvestEnd;
  final String farmerProfileId;
  final String supplyCommitmentId;
  final String farmName;
  final String farmerName;
  final String parish;
  final String supplyStatus;
  final double confirmedQuantity;
  final DateTime? expectedHarvestDate;
  final String latestStage;
  final String latestMessage;
  final String latestImageUrl;
  final DateTime? latestUpdateAt;
  final String receivingBatchId;
  final String lotCode;
  final String qualityGrade;
  final double acceptedQuantity;
  final DateTime? collectionDate;
  final DateTime? receivedAt;
  final DateTime? completedAt;
  final bool exactLotVerified;
  final String traceLevel;
  final String traceMessage;

  const HpjFarmPassportSource({
    required this.snapshotId,
    required this.sourceKey,
    required this.orderId,
    required this.circleId,
    required this.productId,
    required this.productName,
    required this.imageUrl,
    required this.unit,
    required this.reservedQuantity,
    required this.orderedQuantity,
    required this.harvestStart,
    required this.harvestEnd,
    required this.farmerProfileId,
    required this.supplyCommitmentId,
    required this.farmName,
    required this.farmerName,
    required this.parish,
    required this.supplyStatus,
    required this.confirmedQuantity,
    required this.expectedHarvestDate,
    required this.latestStage,
    required this.latestMessage,
    required this.latestImageUrl,
    required this.latestUpdateAt,
    required this.receivingBatchId,
    required this.lotCode,
    required this.qualityGrade,
    required this.acceptedQuantity,
    required this.collectionDate,
    required this.receivedAt,
    required this.completedAt,
    required this.exactLotVerified,
    required this.traceLevel,
    required this.traceMessage,
  });

  factory HpjFarmPassportSource.fromSupabase(Map<String, dynamic> data) {
    double number(dynamic value) {
      if (value is num) return value.toDouble();
      return double.tryParse(value?.toString() ?? '') ?? 0;
    }

    bool boolean(dynamic value) {
      if (value is bool) return value;
      final clean = value?.toString().trim().toLowerCase() ?? '';
      return clean == 'true' || clean == 't' || clean == '1';
    }

    return HpjFarmPassportSource(
      snapshotId: (data['snapshot_id'] ?? '').toString(),
      sourceKey: (data['source_key'] ?? '').toString(),
      orderId: (data['order_id'] ?? '').toString(),
      circleId: (data['circle_id'] ?? '').toString(),
      productId: (data['product_id'] ?? '').toString(),
      productName:
          (data['product_name'] ?? 'Harvest product').toString().trim(),
      imageUrl: (data['image_url'] ?? '').toString().trim(),
      unit: (data['unit'] ?? 'unit').toString().trim(),
      reservedQuantity: number(data['reserved_quantity']),
      orderedQuantity: number(data['ordered_quantity']),
      harvestStart: parseProductDate(data['harvest_start']),
      harvestEnd: parseProductDate(data['harvest_end']),
      farmerProfileId: (data['farmer_profile_id'] ?? '').toString(),
      supplyCommitmentId: (data['supply_commitment_id'] ?? '').toString(),
      farmName: (data['farm_name'] ?? '').toString().trim(),
      farmerName: (data['farmer_name'] ?? '').toString().trim(),
      parish: (data['parish'] ?? '').toString().trim(),
      supplyStatus:
          (data['supply_status'] ?? '').toString().trim().toLowerCase(),
      confirmedQuantity: number(data['confirmed_quantity']),
      expectedHarvestDate: parseProductDate(data['expected_harvest_date']),
      latestStage:
          (data['latest_stage'] ?? '').toString().trim().toLowerCase(),
      latestMessage: (data['latest_message'] ?? '').toString().trim(),
      latestImageUrl: (data['latest_image_url'] ?? '').toString().trim(),
      latestUpdateAt: parseProductDate(data['latest_update_at']),
      receivingBatchId: (data['receiving_batch_id'] ?? '').toString(),
      lotCode: (data['lot_code'] ?? '').toString().trim(),
      qualityGrade: (data['quality_grade'] ?? '').toString().trim(),
      acceptedQuantity: number(data['accepted_quantity']),
      collectionDate: parseProductDate(data['collection_date']),
      receivedAt: parseProductDate(data['received_at']),
      completedAt: parseProductDate(data['completed_at']),
      exactLotVerified: boolean(data['exact_lot_verified']),
      traceLevel:
          (data['trace_level'] ?? 'harvest_linked').toString().trim().toLowerCase(),
      traceMessage: (data['trace_message'] ?? '').toString().trim(),
    );
  }

  bool get hasFarmer => farmerProfileId.isNotEmpty || farmName.isNotEmpty;
  bool get hasFieldUpdate => latestStage.isNotEmpty;
  bool get hasVerifiedSupply =>
      supplyStatus == 'confirmed' || supplyStatus == 'fulfilled';
  bool get hasReceiving => receivingBatchId.isNotEmpty;

  String get farmDisplayName {
    if (farmName.isNotEmpty) return farmName;
    if (farmerName.isNotEmpty) return farmerName;
    return 'HPJ harvest network';
  }

  String get sourceLocation {
    final values = <String>[
      if (farmerName.isNotEmpty && farmerName != farmName) farmerName,
      if (parish.isNotEmpty) parish,
    ];
    return values.join(' • ');
  }

  String get traceLabel {
    if (exactLotVerified) return 'Exact lot verified';
    switch (traceLevel) {
      case 'receiving_verified':
        return 'HPJ receiving verified';
      case 'supply_verified':
        return 'HPJ supply verified';
      case 'field_verified':
        return 'Field story verified';
      default:
        return 'Harvest linked';
    }
  }
}

Future<List<HpjFarmPassportSource>> fetchHpjOrderFarmPassport(
  String orderId,
) async {
  final cleanId = orderId.trim();
  if (cleanId.isEmpty || !isLoggedIn) {
    return const <HpjFarmPassportSource>[];
  }

  try {
    final response = await supabase.rpc(
      'hpj_get_order_farm_passport',
      params: <String, dynamic>{'p_order_id': cleanId},
    );

    return (response as List)
        .map(
          (row) => HpjFarmPassportSource.fromSupabase(
            Map<String, dynamic>.from(row as Map),
          ),
        )
        .where((item) => item.circleId.isNotEmpty)
        .toList(growable: false);
  } catch (error) {
    farmDebugLog('Farm-to-Box Passport unavailable: $error');
    return const <HpjFarmPassportSource>[];
  }
}

String _hpjPassportNumber(double value) {
  if (value == value.roundToDouble()) return value.toInt().toString();
  return value.toStringAsFixed(1);
}

String _hpjPassportDate(DateTime? value) {
  if (value == null) return '';
  final local = value.toLocal();
  const months = <String>[
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
  ];
  return '${local.day} ${months[local.month - 1]} ${local.year}';
}

String _hpjPassportHarvestWindow(HpjFarmPassportSource item) {
  final start = _hpjPassportDate(item.harvestStart);
  final end = _hpjPassportDate(item.harvestEnd);
  if (start.isEmpty && end.isEmpty) return 'Harvest window not published';
  if (end.isEmpty || start == end) return start;
  if (start.isEmpty) return end;
  return '$start – $end';
}

int _hpjPassportStrength(HpjFarmPassportSource item) {
  if (item.exactLotVerified) return 5;
  switch (item.traceLevel) {
    case 'receiving_verified':
      return 4;
    case 'supply_verified':
      return 3;
    case 'field_verified':
      return 2;
    default:
      return 1;
  }
}

String _hpjPassportBestLabel(List<HpjFarmPassportSource> items) {
  if (items.isEmpty) return 'No trace record';
  final best = List<HpjFarmPassportSource>.from(items)
    ..sort((a, b) => _hpjPassportStrength(b).compareTo(_hpjPassportStrength(a)));
  return best.first.traceLabel;
}

Map<String, List<HpjFarmPassportSource>> _hpjPassportGroupByHarvest(
  List<HpjFarmPassportSource> items,
) {
  final output = <String, List<HpjFarmPassportSource>>{};
  for (final item in items) {
    final key = item.circleId.isNotEmpty
        ? item.circleId
        : '${item.productId}:${item.productName.toLowerCase()}';
    output.putIfAbsent(key, () => <HpjFarmPassportSource>[]).add(item);
  }
  return output;
}

