class HpjFarmToBoxPassportScreen extends StatefulWidget {
  final String orderId;
  final List<HpjFarmPassportSource>? initialSources;

  const HpjFarmToBoxPassportScreen({
    super.key,
    required this.orderId,
    this.initialSources,
  });

  @override
  State<HpjFarmToBoxPassportScreen> createState() =>
      _HpjFarmToBoxPassportScreenState();
}

class _HpjFarmToBoxPassportScreenState
    extends State<HpjFarmToBoxPassportScreen> {
  late Future<List<HpjFarmPassportSource>> future;

  @override
  void initState() {
    super.initState();
    final initial = widget.initialSources;
    future = initial != null && initial.isNotEmpty
        ? Future<List<HpjFarmPassportSource>>.value(initial)
        : fetchHpjOrderFarmPassport(widget.orderId);
  }

  Future<void> _refresh() async {
    final next = fetchHpjOrderFarmPassport(widget.orderId);
    if (mounted) setState(() => future = next);
    await next;
  }

  @override
  Widget build(BuildContext context) {
    final desktop = kIsWeb && MediaQuery.sizeOf(context).width >= 980;

    return Scaffold(
      backgroundColor: const Color(0xFFF5F7F1),
      appBar: AppBar(
        backgroundColor: Colors.white,
        surfaceTintColor: Colors.white,
        title: const Text(
          'Farm-to-Box Passport',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
      ),
      body: RefreshIndicator(
        onRefresh: _refresh,
        child: FutureBuilder<List<HpjFarmPassportSource>>(
          future: future,
          builder: (context, snapshot) {
            final items =
                snapshot.data ?? const <HpjFarmPassportSource>[];

            if (snapshot.connectionState == ConnectionState.waiting &&
                items.isEmpty) {
              return ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                children: const [
                  SizedBox(height: 230),
                  Center(child: CircularProgressIndicator()),
                ],
              );
            }

            if (items.isEmpty) {
              return ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                padding: const EdgeInsets.all(18),
                children: const [
                  SizedBox(height: 50),
                  _HpjPassportEmpty(),
                ],
              );
            }

            final grouped = _hpjPassportGroupByHarvest(items);

            return ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: EdgeInsets.fromLTRB(
                desktop ? 34 : 16,
                desktop ? 28 : 16,
                desktop ? 34 : 16,
                54,
              ),
              children: [
                Center(
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 1080),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        _HpjPassportHero(
