class _HpjPassportHero extends StatelessWidget {
  final String orderId;
  final List<HpjFarmPassportSource> items;

  const _HpjPassportHero({
    required this.orderId,
    required this.items,
  });

  @override
  Widget build(BuildContext context) {
    final groups = _hpjPassportGroupByHarvest(items);
    final farms = items
        .map((item) => item.farmDisplayName)
        .where((name) => name != 'HPJ harvest network')
        .toSet();
    final short = orderId.replaceAll('-', '').toUpperCase();
    final displayOrder = short.length > 8 ? short.substring(0, 8) : short;

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(21),
      decoration: BoxDecoration(
        gradient: const LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [Color(0xFF063C2B), Color(0xFF176044)],
        ),
        borderRadius: BorderRadius.circular(28),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF073F2C).withOpacity(.15),
            blurRadius: 28,
            offset: const Offset(0, 11),
          ),
        ],
      ),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final wide = constraints.maxWidth >= 720;

          final copy = Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'HPJ FARM-TO-BOX PASSPORT',
                style: TextStyle(
                  color: Color(0xFFFFD55A),
                  fontSize: 8.8,
                  letterSpacing: .9,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 7),
              const Text(
                'See the verified story behind your food.',
                style: TextStyle(
                  color: Colors.white,
                  fontSize: 26,
                  height: 1.05,
                  letterSpacing: -.45,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 8),
              Text(
                'Order #$displayOrder • GrowTogether harvest trace',
                style: TextStyle(
                  color: Colors.white.withOpacity(.73),
                  fontSize: 10.3,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ],
          );

          final metrics = Container(
            padding: const EdgeInsets.all(14),
            decoration: BoxDecoration(
              color: Colors.white.withOpacity(.08),
              borderRadius: BorderRadius.circular(19),
              border: Border.all(color: Colors.white.withOpacity(.10)),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                _HpjPassportHeroMetric(
                  value: '${groups.length}',
                  label: 'Harvests',
                ),
                const SizedBox(width: 20),
                _HpjPassportHeroMetric(
                  value: '${farms.length}',
                  label: 'Farms',
                ),
                const SizedBox(width: 20),
                _HpjPassportHeroMetric(
                  value: _hpjPassportBestLabel(items),
                  label: 'Strongest trace',
                  compact: true,
                ),
              ],
            ),
          );

          if (!wide) {
            return Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                copy,
                const SizedBox(height: 16),
                SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  child: metrics,
                ),
              ],
            );
          }

          return Row(
            children: [
              Expanded(child: copy),
              const SizedBox(width: 24),
              metrics,
            ],
          );
        },
      ),
    );
  }
}

