class _HpjPassportPath extends StatelessWidget {
  final List<HpjFarmPassportSource> sources;

  const _HpjPassportPath({
    required this.sources,
  });

  @override
  Widget build(BuildContext context) {
    final hasSupply = sources.any((item) => item.hasVerifiedSupply);
    final hasField = sources.any((item) => item.hasFieldUpdate);
    final hasReceiving = sources.any((item) => item.hasReceiving);
    final exactLot = sources.any((item) => item.exactLotVerified);

    final steps = <({String label, bool done, IconData icon})>[
      (
        label: 'Reserved',
        done: true,
        icon: Icons.groups_2_outlined,
      ),
      (
        label: 'Supply verified',
        done: hasSupply,
        icon: Icons.verified_outlined,
      ),
      (
        label: 'Field story',
        done: hasField,
        icon: Icons.eco_outlined,
      ),
      (
        label: exactLot ? 'Exact HPJ lot' : 'HPJ receiving',
        done: exactLot || hasReceiving,
        icon: Icons.warehouse_outlined,
      ),
      (
        label: 'Your order',
        done: true,
        icon: Icons.shopping_bag_outlined,
      ),
    ];

    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxWidth < 650;

        if (compact) {
          return Wrap(
            spacing: 6,
            runSpacing: 6,
            children: steps
                .map(
                  (step) => _HpjPassportPathChip(
                    label: step.label,
                    done: step.done,
                    icon: step.icon,
                  ),
                )
                .toList(growable: false),
          );
        }

        return Row(
          children: List<Widget>.generate(steps.length, (index) {
            final step = steps[index];
            return Expanded(
              child: Row(
                children: [
                  Expanded(
                    child: _HpjPassportPathTile(
                      label: step.label,
                      done: step.done,
                      icon: step.icon,
                    ),
                  ),
                  if (index != steps.length - 1)
                    const Padding(
                      padding: EdgeInsets.symmetric(horizontal: 4),
                      child: Icon(
                        Icons.arrow_forward_rounded,
                        color: Color(0xFFBCC6BF),
                        size: 15,
                      ),
                    ),
                ],
              ),
            );
          }),
        );
      },
    );
  }
}

