class HpjRescueHarvestScreen extends StatefulWidget {
  const HpjRescueHarvestScreen({super.key});

  @override
  State<HpjRescueHarvestScreen> createState() => _HpjRescueHarvestScreenState();
}

class _HpjRescueHarvestScreenState extends State<HpjRescueHarvestScreen> {
  late Future<List<HpjRescueHarvest>> future;

  @override
  void initState() {
    super.initState();
    future = fetchHpjRescueHarvests();
  }

  Future<void> _refresh() async {
    final next = fetchHpjRescueHarvests();
    if (mounted) setState(() => future = next);
    await next;
  }

  Future<bool> _requireLogin() async {
    if (isLoggedIn) return true;
    final result = await Navigator.of(context).push<bool>(
      MaterialPageRoute<bool>(
        builder: (_) => const LoginScreen(returnToPrevious: true),
      ),
    );
    return result == true || isLoggedIn;
  }

  Future<void> _rescue(HpjRescueHarvest item) async {
    if (!await _requireLogin()) return;
    if (!mounted) return;
    final changed = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _HpjRescueReserveSheet(item: item),
    );
    if (changed == true && mounted) await _refresh();
  }

  @override
  Widget build(BuildContext context) {
    final desktop = kIsWeb && MediaQuery.sizeOf(context).width >= 980;
    return Scaffold(
      backgroundColor: const Color(0xFFFFFBF2),
      appBar: AppBar(
        backgroundColor: Colors.white,
        surfaceTintColor: Colors.white,
        title: const Text(
          'Rescue Harvest',
          style: TextStyle(fontWeight: FontWeight.w900),
        ),
      ),
      body: RefreshIndicator(
        onRefresh: _refresh,
        child: FutureBuilder<List<HpjRescueHarvest>>(
          future: future,
          builder: (context, snapshot) {
            final rows = snapshot.data ?? const <HpjRescueHarvest>[];
            return ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: EdgeInsets.fromLTRB(
                desktop ? 34 : 16,
                desktop ? 28 : 16,
                desktop ? 34 : 16,
                48,
              ),
              children: [
                Center(
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 1120),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        _HpjRescueHero(activeCount: rows.length),
                        const SizedBox(height: 15),
                        if (snapshot.connectionState == ConnectionState.waiting &&
                            rows.isEmpty)
                          const SizedBox(
                            height: 260,
                            child: Center(child: CircularProgressIndicator()),
                          )
                        else if (rows.isEmpty)
                          const _HpjRescueEmpty()
                        else
                          LayoutBuilder(
                            builder: (context, constraints) {
                              final cols = constraints.maxWidth >= 900 ? 2 : 1;
                              final gap = 13.0;
                              final width = cols == 1
                                  ? constraints.maxWidth
                                  : (constraints.maxWidth - gap) / 2;
                              return Wrap(
                                spacing: gap,
                                runSpacing: gap,
                                children: rows
                                    .map(
                                      (item) => SizedBox(
                                        width: width,
                                        child: _HpjRescueCard(
                                          item: item,
                                          onRescue: () => _rescue(item),
                                        ),
                                      ),
                                    )
                                    .toList(growable: false),
                              );
                            },
                          ),
                      ],
                    ),
                  ),
                ),
              ],
            );
          },
        ),
      ),
    );
  }
}

