  Future<void> _openNutritionPicker(BuildContext context) async {
    const nutrients = <String>[
      'Magnesium',
      'Iron',
      'Fiber',
      'Potassium',
      'Vitamin C',
      'Protein',
      'Calcium',
      'Antioxidants',
    ];

    final selected = await showModalBottomSheet<String>(
      context: context,
      useSafeArea: true,
      showDragHandle: true,
      builder: (sheetContext) {
        return Padding(
          padding: const EdgeInsets.fromLTRB(18, 4, 18, 24),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'Shop by nutrition',
