class AccountActionGrid extends StatelessWidget {
  final List<AccountActionItem> actions;

  const AccountActionGrid({
    super.key,
    required this.actions,
  });

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final availableWidth = constraints.maxWidth;
        final desktopWeb = HpjWebUi.isDesktop(context);
        final columns = desktopWeb
            ? 4
            : (availableWidth >= 560 ? 3 : 2);
        final spacing = desktopWeb ? 14.0 : 10.0;
        final tileWidth = (availableWidth - spacing * (columns - 1)) / columns;

        return Wrap(
          spacing: spacing,
          runSpacing: spacing,
          children: actions
              .map(
                (action) => SizedBox(
                  width: tileWidth,
                  child: AccountActionTile(action: action),
                ),
              )
              .toList(),
        );
      },
    );
  }
}

