enum _HPJHeroStyle {
  freshBox,
  meals,
  deals,
  farm,
}

class _HPJSwipePromoCard extends StatelessWidget {
  final _HPJHeroStyle style;
  final String eyebrow;
  final String title;
  final String subtitle;
  final String? meta;
  final List<String> badges;
  final String ctaLabel;
  final String? imageUrl;
  final IconData fallbackIcon;
  final VoidCallback onTap;

  const _HPJSwipePromoCard({
    this.style = _HPJHeroStyle.freshBox,
    required this.eyebrow,
    required this.title,
    required this.subtitle,
    required this.ctaLabel,
    required this.onTap,
    this.meta,
    this.badges = const [],
    this.imageUrl,
    this.fallbackIcon = Icons.eco_rounded,
  });

  bool get _lightText {
    return style == _HPJHeroStyle.meals || style == _HPJHeroStyle.farm;
  }

  Color get _accentColor {
    switch (style) {
      case _HPJHeroStyle.freshBox:
        return const Color(0xFF0B4C36);
      case _HPJHeroStyle.meals:
        return const Color(0xFFD8A33B);
      case _HPJHeroStyle.deals:
        return const Color(0xFFB86C3B);
      case _HPJHeroStyle.farm:
        return const Color(0xFF1F6B46);
    }
  }

  Color get _fallbackBackground {
    switch (style) {
      case _HPJHeroStyle.freshBox:
        return const Color(0xFFF6F2E8);
      case _HPJHeroStyle.meals:
        return const Color(0xFF163729);
      case _HPJHeroStyle.deals:
        return const Color(0xFFF6EEE0);
      case _HPJHeroStyle.farm:
        return const Color(0xFF123326);
    }
  }

  String? _usableImageUrl() {
    final raw = imageUrl?.trim() ?? '';
    if (raw.isEmpty) return null;
    return cleanHostedImageUrl(raw) ?? raw;
  }

  Widget _buildBackground() {
    final url = _usableImageUrl();

    if (url == null) {
      return Container(
        color: _fallbackBackground,
        alignment: Alignment.centerRight,
        padding: const EdgeInsets.only(right: 26),
        child: Icon(
          fallbackIcon,
          size: 92,
          color: _lightText
              ? Colors.white.withOpacity(0.14)
              : _accentColor.withOpacity(0.18),
        ),
      );
    }

    return Image.network(
      url,
      fit: BoxFit.cover,
      alignment: Alignment.center,
      gaplessPlayback: true,
      cacheWidth: 1400,
      filterQuality: FilterQuality.high,
      loadingBuilder: (context, child, progress) {
        if (progress == null) return child;
        return ColoredBox(color: _fallbackBackground);
      },
      errorBuilder: (_, __, ___) => Container(
        color: _fallbackBackground,
        alignment: Alignment.centerRight,
        padding: const EdgeInsets.only(right: 26),
        child: Icon(
          fallbackIcon,
          size: 92,
          color: _lightText
              ? Colors.white.withOpacity(0.14)
              : _accentColor.withOpacity(0.18),
        ),
      ),
    );
  }

  Widget _infoChip(String text) {
    return Container(
      constraints: const BoxConstraints(maxWidth: 150),
      padding: const EdgeInsets.symmetric(
        horizontal: 9,
        vertical: 5,
      ),
      decoration: BoxDecoration(
        color: _lightText
            ? Colors.white.withOpacity(0.14)
            : const Color(0xFFFFFEFB).withOpacity(0.84),
        borderRadius: BorderRadius.circular(999),
        border: Border.all(
          color: _lightText
              ? Colors.white.withOpacity(0.20)
              : const Color(0xFFE8E0D2),
        ),
      ),
      child: Text(
        text,
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: TextStyle(
          color: _lightText ? Colors.white : FarmColors.deepGreen,
          fontSize: 9.5,
          fontWeight: FontWeight.w800,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final displayBadges = <String>[
      ...badges.where((item) => item.trim().isNotEmpty),
      if (badges.isEmpty && meta != null && meta!.trim().isNotEmpty)
        meta!.trim(),
    ];

    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxWidth < 350;
        final phoneCompact = constraints.maxWidth < 430;

        return Container(
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(28),
            border: Border.all(
              color: _lightText
                  ? Colors.white.withOpacity(0.10)
                  : const Color(0xFFE5DED1),
            ),
            boxShadow: [
              BoxShadow(
                color: const Color(0xFF12382C).withOpacity(0.12),
                blurRadius: 28,
                offset: const Offset(0, 13),
              ),
            ],
          ),
          child: Material(
            color: _fallbackBackground,
            borderRadius: BorderRadius.circular(28),
            clipBehavior: Clip.antiAlias,
            child: InkWell(
              onTap: onTap,
              child: Stack(
                fit: StackFit.expand,
                children: [
                  _buildBackground(),
                  DecoratedBox(
                    decoration: BoxDecoration(
                      gradient: LinearGradient(
                        begin: Alignment.centerLeft,
                        end: Alignment.centerRight,
                        colors: _lightText
                            ? [
                                const Color(0xFF082A20).withOpacity(0.91),
                                const Color(0xFF082A20).withOpacity(0.72),
                                const Color(0xFF082A20).withOpacity(0.26),
                                Colors.transparent,
                              ]
                            : [
                                const Color(0xFFFFFBF2).withOpacity(0.98),
                                const Color(0xFFFFFBF2).withOpacity(0.88),
                                const Color(0xFFFFFBF2).withOpacity(0.38),
                                Colors.transparent,
                              ],
                        stops: const [0.0, 0.46, 0.76, 1.0],
                      ),
                    ),
                  ),
