  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> {
  bool _homeSocialIsFavorite(Product product) {
    final callback = widget.isFavorite;
    if (callback != null) {
      return callback(product);
    }

    final productId = product.id.trim();
    if (productId.isEmpty) return false;

    return widget.favoriteProducts.any(
      (favorite) => favorite.id.trim() == productId,
    );
  }

  void _homeSocialToggleFavorite(Product product) {
    final callback = widget.onToggleFavorite;
    if (callback != null) {
      callback(product);
      return;
    }

    // Backward-compatible fallback for older root wiring.
    // Persist the favorite even when the parent has not yet supplied
    // the Phase60 in-memory callback.
    final nextValue = !_homeSocialIsFavorite(product);
    unawaited(
      setFavoriteForCurrentUser(
        product,
        isFavorite: nextValue,
      ),
    );
  }

  void _showDealsOnHome() {
    homeSearchFocusNode.unfocus();
    homeSearchController.clear();

    setState(() {
      homeSearchQuery = '';
      selectedHomeCategory = 'All';
      selectedHomeNutrient = 'All';
      selectedHomeAvailability = 'Any availability';
      selectedHomePrice = 'Any price';
      selectedHomeFarm = 'All farms';
      selectedHomeSpecial = 'Deals';
      selectedHomeSort = 'Recommended';
    });
  }

  late Future<List<Product>> homeProductsFuture;
  late Future<List<Product>> buyAgainProductsFuture;
  late Future<CustomerProfile?> customerProfileFuture;
  late Future<LoyaltySummary> loyaltySummaryFuture;
  late Future<List<HomeHeroSlide>> homeHeroSlidesFuture;
  late Future<List<FarmOrder>> homeOrdersFuture;
  late Future<HpjSponsorCampaign?> sponsoredCampaignFuture;
  late Future<List<FarmPublicProfileRecord>> socialFarmsFuture;
  // Never assume that Admin social switches are ON while loading.
  _HpjCustomerHomeSocialVisibility _homeSocialVisibility =
      _HpjCustomerHomeSocialVisibility.hidden;
  int _homeSocialVisibilityRequest = 0;
  List<Product> cachedHomeProducts = const <Product>[];
  List<Product> homeRecentlyViewedProducts = const <Product>[];
  final TextEditingController homeSearchController = TextEditingController();
  final FocusNode homeSearchFocusNode = FocusNode();
  String homeSearchQuery = '';
  String selectedHomeCategory = 'All';
  String selectedHomeNutrient = 'All';
  String selectedHomeAvailability = 'Any availability';
  String selectedHomePrice = 'Any price';
  String selectedHomeFarm = 'All farms';
  String selectedHomeSpecial = 'All';
  String selectedHomeSort = 'Recommended';
  int agricultureFeedRefreshKey = 0;

  // HPJ MOBILE VISUAL MATCH — native Home mirrors the clean community-first
  // reference while all existing commerce/social systems stay intact.
  Set<String> _mobileFollowedFarmIds = <String>{};
  Set<String> _mobileFollowedProductIds = <String>{};
  Set<String> _mobileFollowedCategories = <String>{};
  String _homeNearArea = 'St. Elizabeth';
  bool _homeNearAreaReady = false;

  @override
  void initState() {
    super.initState();
    hpjCustomerParishPreference.addListener(
      _applySharedCustomerParishPreference,
    );
    homeProductsFuture = loadHomeProducts();
    buyAgainProductsFuture = fetchBuyAgainProductsForCustomerUi();
    homeOrdersFuture = fetchOrders();
    sponsoredCampaignFuture = fetchActiveCustomerHomeSponsor();
    socialFarmsFuture = fetchPublishedFarmPublicProfiles(limit: 12);
    unawaited(_reloadCustomerHomeSocialVisibility());
    unawaited(_loadHomeRecentlyViewed());
    unawaited(_loadUserPreferences());
    customerProfileFuture = fetchCurrentCustomerProfile();
    loyaltySummaryFuture = fetchLoyaltySummary();
    homeHeroSlidesFuture = fetchPublicHomeHeroSlides();
    if (!kIsWeb) {
      unawaited(_loadMobileReferenceSocialState());
      unawaited(_loadHomeNearArea());
    } else {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted || !hpjUseMobileAppPresentation(context)) return;
        unawaited(_loadMobileReferenceSocialState());
        unawaited(_loadHomeNearArea());
      });
    }
    homeSearchFocusNode.addListener(() {
      if (mounted) setState(() {});
    });
  }


  // Read the same persisted flags used by Admin -> Workspace Control Center.
  // This direct read deliberately does not call
  // hpjFarmerSocialFeatureVisibleToCurrentUser(), which allows Owner preview
  // even while OFF. Here the Home must reflect the actual saved switch state.
  Future<void> _reloadCustomerHomeSocialVisibility() async {
    final request = ++_homeSocialVisibilityRequest;
    _HpjCustomerHomeSocialVisibility next =
        _HpjCustomerHomeSocialVisibility.hidden;
    try {
      final row = await supabase
          .from('marketplace_program_settings')
          .select('farmer_stories_enabled, farmer_community_enabled')
          .eq('id', 'default')
          .maybeSingle();

      // Missing settings or inaccessible controls: hide the social previews
      // instead of displaying content that an Admin may have disabled.
      if (row != null) {
        next = _HpjCustomerHomeSocialVisibility(
          showStories: row['farmer_stories_enabled'] == true,
          showCommunity: row['farmer_community_enabled'] == true,
        );
      }
    } catch (error) {
      farmDebugLog('Customer Home social visibility unavailable: $error');
    }

    if (!mounted || request != _homeSocialVisibilityRequest) return;
    setState(() => _homeSocialVisibility = next);
  }

  void _applySharedCustomerParishPreference() {
    final next = _hpjCanonicalCustomerParish(
      hpjCustomerParishPreference.value,
    );

    if (!mounted || next == _homeNearArea) return;

    setState(() {
      _homeNearArea = next;
      _homeNearAreaReady = true;
    });
  }

  Future<void> _loadHomeNearArea() async {
    try {
      final saved = await HpjSmartLocalStore.readString('shop_near_area');
      final checkout = await HpjSmartLocalStore.readString('checkout_zone');
      final value = (saved ?? '').trim().isNotEmpty
          ? saved!.trim()
          : (checkout ?? '').trim().isNotEmpty
              ? checkout!.trim()
              : 'St. Elizabeth';

      if (!mounted) return;

      final canonical = _hpjCanonicalCustomerParish(value);

      setState(() {
        _homeNearArea = canonical;
        _homeNearAreaReady = true;
      });

      if (hpjCustomerParishPreference.value != canonical) {
        hpjCustomerParishPreference.value = canonical;
      }
    } catch (_) {
      if (!mounted) return;
      setState(() => _homeNearAreaReady = true);
    }
  }

  Future<void> _openHomeParishPicker() async {
    const parishes = <String>[
      'Hanover',
      'Westmoreland',
      'St. James',
      'Trelawny',
      'St. Elizabeth',
      'Manchester',
      'Clarendon',
      'St. Ann',
      'St. Catherine',
      'St. Mary',
      'St. Andrew',
      'Kingston',
      'Portland',
      'St. Thomas',
    ];

    final selected = await showModalBottomSheet<String>(
      context: context,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return Container(
          constraints: BoxConstraints(
            maxHeight: MediaQuery.sizeOf(sheetContext).height * .72,
          ),
          decoration: const BoxDecoration(
            color: Color(0xFFFFFEFB),
            borderRadius: BorderRadius.vertical(
              top: Radius.circular(28),
            ),
          ),
          child: Column(
            children: [
              const SizedBox(height: 10),
              Container(
                width: 42,
                height: 4,
                decoration: BoxDecoration(
                  color: const Color(0xFFD7DDD4),
                  borderRadius: BorderRadius.circular(999),
                ),
              ),
              const Padding(
                padding: EdgeInsets.fromLTRB(18, 18, 18, 8),
                child: Row(
                  children: [
                    Icon(
                      Icons.location_on_rounded,
                      color: FarmColors.green,
                      size: 21,
                    ),
                    SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        'Choose your parish',
                        style: TextStyle(
                          color: FarmColors.deepGreen,
                          fontSize: 20,
                          fontWeight: FontWeight.w900,
                          letterSpacing: -.3,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              const Padding(
                padding: EdgeInsets.fromLTRB(18, 0, 18, 12),
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                    'HPJ will show farms and produce from this parish first, then the rest of Jamaica.',
                    style: TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 11.5,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
              ),
              const Divider(height: 1),
              Expanded(
                child: ListView.separated(
                  padding: const EdgeInsets.fromLTRB(10, 8, 10, 18),
                  itemCount: parishes.length,
                  separatorBuilder: (_, __) => const SizedBox(height: 2),
                  itemBuilder: (context, index) {
                    final value = parishes[index];
                    final selectedNow =
                        _homeNearKey(value) == _homeNearKey(_homeNearArea);

                    return ListTile(
                      dense: true,
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(16),
                      ),
                      tileColor: selectedNow
                          ? const Color(0xFFEAF3E7)
                          : Colors.transparent,
                      leading: Icon(
                        selectedNow
                            ? Icons.check_circle_rounded
                            : Icons.location_on_outlined,
                        color: selectedNow
                            ? FarmColors.green
                            : FarmColors.mutedText,
                        size: 20,
                      ),
                      title: Text(
                        value,
                        style: TextStyle(
                          color: FarmColors.deepGreen,
                          fontWeight:
                              selectedNow ? FontWeight.w900 : FontWeight.w800,
                        ),
                      ),
                      trailing: selectedNow
                          ? const Text(
                              'Selected',
                              style: TextStyle(
                                color: FarmColors.green,
                                fontSize: 10,
                                fontWeight: FontWeight.w900,
                              ),
                            )
                          : null,
                      onTap: () => Navigator.of(sheetContext).pop(value),
                    );
                  },
                ),
              ),
            ],
          ),
        );
      },
    );

    if (!mounted || selected == null || selected.trim().isEmpty) return;

    final clean = _hpjCanonicalCustomerParish(selected.trim());
    setState(() {
      _homeNearArea = clean;
      _homeNearAreaReady = true;
    });

    await HpjSmartLocalStore.writeString('shop_near_area', clean);

    if (hpjCustomerParishPreference.value != clean) {
      hpjCustomerParishPreference.value = clean;
    }

    // Keep Shop in sync so the same parish is selected when the customer opens it.
    hpjShopParishRequest.value = clean;
  }

  String _homeNearKey(String value) => value
      .trim()
      .toLowerCase()
      .replaceAll('saint ', 'st ')
      .replaceAll('.', '')
      .replaceAll(' parish', '')
      .replaceAll(RegExp(r'\s+'), ' ');

  List<Product> _homeNearbyProducts(List<Product> products) {
    final target = _homeNearKey(_homeNearArea);
    if (target.isEmpty) return const <Product>[];

    final rows = products.where((product) {
      if (!isVisibleCustomerProduct(product) || !product.canAddToCart) {
        return false;
      }
      final parish = _homeNearKey((product.parish ?? '').trim());
      return parish.isNotEmpty && parish == target;
    }).toList();

    rows.sort((a, b) {
      if (a.isLowStock != b.isLowStock) return a.isLowStock ? -1 : 1;
      if (a.hasActiveDiscount != b.hasActiveDiscount) {
        return a.hasActiveDiscount ? -1 : 1;
      }
      return a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });

    // Keep more nearby items available for horizontal swiping.
    return rows.take(20).toList(growable: false);
  }

  Future<void> _loadMobileReferenceSocialState() async {
    if (!hpjUseMobileAppPresentation(context)) return;

    try {
      final values = await Future.wait<dynamic>([
        fetchCurrentUserFollowedFarmIds(),
        fetchHpjFollowedProductIds(),
        fetchHpjFollowedCategoryKeys(),
      ]);

      if (!mounted) return;

      setState(() {
        _mobileFollowedFarmIds = values[0] as Set<String>;
        _mobileFollowedProductIds = values[1] as Set<String>;
        _mobileFollowedCategories = values[2] as Set<String>;
      });
    } catch (error) {
      farmDebugLog('Mobile Home relationship state unavailable: $error');
    }
  }

  Future<void> _toggleMobileProductFollow(Product product) async {
    if (!isLoggedIn || supabase.auth.currentUser == null) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Sign in to follow fresh produce.')),
      );
      return;
    }

    final id = product.id.trim();
    if (id.isEmpty) return;
    final following = _mobileFollowedProductIds.contains(id);

    try {
      await setHpjProductFollow(
        product: product,
        follow: !following,
      );
      if (!mounted) return;
      setState(() {
        if (following) {
          _mobileFollowedProductIds.remove(id);
        } else {
          _mobileFollowedProductIds.add(id);
        }
      });
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _toggleMobileCategoryFollow(String category) async {
    if (!isLoggedIn || supabase.auth.currentUser == null) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Sign in to follow produce categories.')),
      );
      return;
    }

    final key = hpjFreshFollowKey(category);
    if (key.isEmpty) return;
    final following = _mobileFollowedCategories.contains(key);

    try {
      await setHpjCategoryFollow(
        category: category,
        follow: !following,
      );
      if (!mounted) return;
      setState(() {
        if (following) {
          _mobileFollowedCategories.remove(key);
        } else {
          _mobileFollowedCategories.add(key);
        }
      });
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

