                      const SizedBox(height: 10),
                      Wrap(
                        spacing: 8,
                        runSpacing: 8,
                        children: _homeNutrientFilterOptions.map((nutrient) {
                          return sheetChoice(
                            label: nutrient,
                            selected: selectedHomeNutrient == nutrient,
                            onTap: () {
                              setState(() => selectedHomeNutrient = nutrient);
                            },
                          );
                        }).toList(),
                      ),
                      const SizedBox(height: 20),
                      const Text(
                        'Show',
                        style: TextStyle(
                          fontWeight: FontWeight.w900,
                          fontSize: 14,
                          color: FarmColors.ink,
                        ),
                      ),
                      const SizedBox(height: 10),
                      Wrap(
                        spacing: 8,
                        runSpacing: 8,
                        children: _originalAppHomeFilterOptions.map((filter) {
                          final isOutOfStock = filter == 'Out of stock';
                          final isDeal = filter == 'Deals';
                          final color = isOutOfStock
                              ? FarmColors.danger
                              : isDeal
                                  ? FarmColors.warning
                                  : FarmColors.green;

                          return sheetChoice(
                            label: filter,
                            selected: _originalAppSelectedShowFilter == filter,
                            color: color,
                            onTap: () {
                              _applyOriginalAppShowFilter(filter);
                            },
                          );
                        }).toList(),
                      ),
                      const SizedBox(height: 22),
                      Row(
                        children: [
                          Expanded(
                            child: OutlinedButton.icon(
                              onPressed: () {
                                setState(() {
                                  selectedHomeCategory = 'All';
                                  selectedHomeNutrient = 'All';
                                  selectedHomeAvailability =
                                      'Any availability';
                                  selectedHomePrice = 'Any price';
                                  selectedHomeFarm = 'All farms';
                                  selectedHomeSpecial = 'All';
                                  selectedHomeSort = 'Recommended';
                                });
                                sheetSetState(() {});
                              },
                              icon: const Icon(Icons.restart_alt_rounded),
                              label: const Text('Reset'),
                            ),
                          ),
                          const SizedBox(width: 10),
                          Expanded(
                            child: ElevatedButton.icon(
                              onPressed: () {
                                Navigator.pop(sheetContext);
                                homeSearchFocusNode.unfocus();
                              },
                              icon: const Icon(Icons.check_rounded),
                              label: const Text('Apply'),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        );
      },
    );
  }

  Future<void> _showHomeFilterSheet(
    List<Product> products,
  ) async {
    // Native app stays on the pre-website filter presentation.
    if (!kIsWeb) {
      await _showOriginalAppHomeFilterSheet(products);
      return;
    }

    final categories =
        _homeCategoryOptions(products);
    final farms =
        _homeFarmOptions(products);

    if (!farms.contains(selectedHomeFarm)) {
      selectedHomeFarm = 'All farms';
    }

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return StatefulBuilder(
          builder: (context, sheetSetState) {
            final resultCount =
                _homeFilterPreviewCount(products);

            Widget sectionTitle(
              String title, {
              String? helper,
            }) {
              return Column(
                crossAxisAlignment:
                    CrossAxisAlignment.start,
                children: [
                  Text(
                    title,
                    style: const TextStyle(
                      fontWeight:
                          FontWeight.w900,
                      fontSize: 14,
                      color: FarmColors.ink,
                    ),
                  ),
                  if (helper != null) ...[
                    const SizedBox(height: 3),
                    Text(
                      helper,
                      style: const TextStyle(
                        color:
                            FarmColors.mutedText,
                        fontSize: 10.5,
                        height: 1.25,
                        fontWeight:
                            FontWeight.w600,
                      ),
                    ),
                  ],
                ],
              );
            }

            Widget sheetChoice({
              required String label,
              required bool selected,
              required VoidCallback onTap,
              Color color = FarmColors.green,
            }) {
              return ChoiceChip(
                selected: selected,
                label: Text(label),
                onSelected: (_) {
                  onTap();
                  sheetSetState(() {});
                },
                selectedColor: color,
                backgroundColor:
                    FarmColors.primarySoft
                        .withOpacity(0.64),
                labelStyle: TextStyle(
                  color:
                      selected
                          ? Colors.white
                          : color,
                  fontWeight:
                      FontWeight.w900,
                  fontSize: 11.5,
                ),
                materialTapTargetSize:
                    MaterialTapTargetSize
                        .shrinkWrap,
                visualDensity:
                    VisualDensity.compact,
                shape:
                    RoundedRectangleBorder(
                  borderRadius:
                      BorderRadius.circular(999),
                  side: BorderSide(
                    color: selected
                        ? color
                        : color.withOpacity(
                            0.13,
                          ),
                  ),
                ),
              );
            }

            String categoryLabel(
              String category,
            ) {
              final count =
                  _homeCategoryCount(
                products,
                category,
              );

              if (category == 'All') {
                return 'All · $count';
              }

              return '$category · $count';
            }

            String farmLabel(String farm) {
              if (farm == 'All farms') {
                return 'All farms';
              }

              final count =
                  _homeFarmCount(
                products,
                farm,
              );

              return '$farm ($count)';
            }

            return SafeArea(
              top: false,
              child: Padding(
                padding: EdgeInsets.only(
                  left: 12,
                  right: 12,
                  bottom:
                      12 +
                      MediaQuery.of(context)
                          .viewInsets
                          .bottom,
                ),
                child: Container(
                  constraints: BoxConstraints(
                    maxHeight:
                        MediaQuery.of(context)
                                .size
                                .height *
                            0.88,
                    maxWidth: 760,
                  ),
                  decoration: BoxDecoration(
                    color: FarmColors.card,
                    borderRadius:
                        BorderRadius.circular(
                      28,
                    ),
                    border: Border.all(
                      color: FarmColors.line,
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: FarmColors.shadow
                            .withOpacity(0.16),
                        blurRadius: 28,
                        offset:
                            const Offset(0, 16),
                      ),
                    ],
                  ),
                  child: Column(
                    children: [
                      Padding(
                        padding:
                            const EdgeInsets
                                .fromLTRB(
                          18,
                          14,
                          12,
                          0,
                        ),
                        child: Column(
                          children: [
                            Center(
                              child: Container(
                                width: 42,
                                height: 4,
                                decoration:
                                    BoxDecoration(
                                  color:
                                      FarmColors.line,
                                  borderRadius:
                                      BorderRadius
                                          .circular(
                                    99,
