class _HpjSocialCommerceWebHome extends StatefulWidget {
  final List<Product> products;
  final Future<List<FarmPublicProfileRecord>> farmsFuture;
  final List<Product> favoriteProducts;
  final List<Product> recentlyViewedProducts;
  final List<Product> recommendedProducts;
  final int cartItemCount;
  final Future<String> customerNameFuture;
  final VoidCallback onShop;
  final VoidCallback onMyBox;
  final VoidCallback onOrders;
  final VoidCallback onAccount;
  final VoidCallback onOpenReels;
  final void Function(Product product) onAddProduct;
  final void Function(Product product) onOpenProduct;
  final bool Function(Product product) isFavorite;
  final void Function(Product product) onToggleFavorite;
  final Future<void> Function() onRefresh;

  const _HpjSocialCommerceWebHome({
    required this.products,
    required this.farmsFuture,
    required this.favoriteProducts,
    required this.recentlyViewedProducts,
    required this.recommendedProducts,
    required this.cartItemCount,
    required this.customerNameFuture,
    required this.onShop,
    required this.onMyBox,
    required this.onOrders,
    required this.onAccount,
    required this.onOpenReels,
    required this.onAddProduct,
    required this.onOpenProduct,
    required this.isFavorite,
    required this.onToggleFavorite,
    required this.onRefresh,
  });

  @override
  State<_HpjSocialCommerceWebHome> createState() =>
      _HpjSocialCommerceWebHomeState();
}

class _HpjSocialCommerceWebHomeState
    extends State<_HpjSocialCommerceWebHome> {
  String selectedFreshPickFilter = 'All';
  Set<String> followedFarmIds = <String>{};
  Set<String> followedProductIds = <String>{};
  Set<String> followedCategories = <String>{};
  @override
  void initState() {
    super.initState();
    unawaited(_loadFollowedFarms());
    unawaited(_loadFreshFollows());
  }

  Future<void> _loadFollowedFarms() async {
    final ids = await fetchCurrentUserFollowedFarmIds();

    if (!mounted) return;

    setState(() {
      followedFarmIds = ids;
    });
  }

  Future<void> _loadFreshFollows() async {
    final results = await Future.wait<Set<String>>([
      fetchHpjFollowedProductIds(),
      fetchHpjFollowedCategoryKeys(),
    ]);
    if (!mounted) return;
    setState(() {
      followedProductIds = results[0];
      followedCategories = results[1];
    });
  }

  Future<void> _toggleProductFollow(Product product) async {
    if (!isLoggedIn || supabase.auth.currentUser == null) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Sign in to follow fresh produce.')),
      );
      return;
    }
    final id = product.id.trim();
    if (id.isEmpty) return;
    final following = followedProductIds.contains(id);
    try {
      await setHpjProductFollow(product: product, follow: !following);
      if (!mounted) return;
      setState(() {
        if (following) {
          followedProductIds.remove(id);
        } else {
          followedProductIds.add(id);
        }
      });
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }

  Future<void> _toggleCategoryFollow(String category) async {
    if (!isLoggedIn || supabase.auth.currentUser == null) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Sign in to follow produce categories.')),
      );
      return;
    }
    final key = hpjFreshFollowKey(category);
    if (key.isEmpty) return;
    final following = followedCategories.contains(key);
    try {
      await setHpjCategoryFollow(category: category, follow: !following);
      if (!mounted) return;
      setState(() {
        if (following) {
          followedCategories.remove(key);
        } else {
          followedCategories.add(key);
        }
      });
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(friendlyAppError(error))),
      );
    }
  }


  Future<void> _refreshSocialHome() async {
    await Future.wait<void>([
      widget.onRefresh(),
      _loadFollowedFarms(),
      _loadFreshFollows(),
    ]);
  }

  List<FarmPublicProfileRecord> _followedFarms(
    List<FarmPublicProfileRecord> farms,
  ) {
    return farms
        .where(
          (farm) =>
              followedFarmIds.contains(farm.farmerId.trim()),
        )
        .toList();
  }

  List<Product> get _freshPickProducts {
    final rows = widget.products
        .where((product) => !product.isOutOfStock)
        .toList();

    int score(Product product) {
      var value = 0;

      if (followedProductIds.contains(product.id.trim())) value += 180;
      if (followedCategories.contains(hpjFreshFollowKey(product.category))) value += 110;
      if (product.hasActiveDiscount) value += 120;
      if (product.isOrganic) value += 100;
      if (isProductHarvestedThisWeek(product)) value += 85;
      if (product.isLocal) value += 45;
      if (product.canAddToCart) value += 30;
      if (product.isLowStock) value += 15;

      return value;
    }

    rows.sort((a, b) {
      final scoreCompare = score(b).compareTo(score(a));
      if (scoreCompare != 0) return scoreCompare;

      return a.name.toLowerCase().compareTo(
            b.name.toLowerCase(),
          );
    });

    return rows;
  }

  List<Product> get _filteredFreshPickProducts {
    switch (selectedFreshPickFilter) {
      case 'Deals':
        return _freshPickProducts
            .where((product) => product.hasActiveDiscount)
            .toList();

      case 'Organic':
        return _freshPickProducts
            .where((product) => product.isOrganic)
            .toList();

      case 'Fresh This Week':
        return _freshPickProducts
            .where(isProductHarvestedThisWeek)
            .toList();

      case 'All':
      default:
        return _freshPickProducts;
    }
  }

  List<Product> get _personalizedProducts {
    if (widget.recommendedProducts.isNotEmpty) {
      return widget.recommendedProducts;
    }

    // Safe fallback for customers without enough history yet.
    return _trendingProducts;
  }

  List<Product> get _trendingProducts {
    final rows = widget.products
        .where((product) => !product.isOutOfStock)
        .toList();

    int score(Product product) {
      var value = 0;
      if (product.isLowStock) value += 90;
      if (product.hasActiveDiscount) value += 70;
      if (isProductHarvestedThisWeek(product)) value += 60;
      if (product.isOrganic) value += 30;
      if (product.isLocal) value += 20;
      if (product.canAddToCart) value += 15;
      return value;
    }

    rows.sort((a, b) {
      final scoreCompare = score(b).compareTo(score(a));
      if (scoreCompare != 0) return scoreCompare;
      return a.name.toLowerCase().compareTo(
            b.name.toLowerCase(),
          );
    });

    return rows.take(10).toList();
  }

  String _productSignal(Product product) {
    if (product.isLowStock) return 'Limited stock';
    if (isProductHarvestedThisWeek(product)) {
      return 'Fresh this week';
    }
    if (product.hasActiveDiscount) return 'Trending now';
    if (product.isOrganic) return 'Organic pick';
    return 'Available now';
  }

  Color _productSignalColor(Product product) {
    if (product.isLowStock) return const Color(0xFFC66E00);
    if (isProductHarvestedThisWeek(product)) {
      return FarmColors.success;
    }
    if (product.hasActiveDiscount) return const Color(0xFFC66E00);
    return FarmColors.primary;
  }

  Future<void> _openFarm(
    FarmPublicProfileRecord farm,
  ) async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => PublicFarmProfileScreen(
          farmerId: farm.farmerId,
          sourceWorkspace: 'customer',
          onAddProduct: widget.onAddProduct,
        ),
      ),
    );

    if (!mounted) return;
    await _loadFollowedFarms();
  }

  Future<void> _openFarms() async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => PublicFarmDirectoryScreen(
          sourceWorkspace: 'customer',
          onAddProduct: widget.onAddProduct,
        ),
      ),
    );
  }

  void _openNutrition() {
    _openWebsiteNutrientBox(context);
  }

  Future<void> _openFollowedFarms() async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => FollowedFarmsScreen(
          sourceWorkspace: 'customer',
          onAddProduct: widget.onAddProduct,
        ),
      ),
    );

    if (!mounted) return;
    await _loadFollowedFarms();
  }


  void _openSaved() {
    Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => FavoritesScreen(
          products: widget.favoriteProducts,
          onShopTap: widget.onShop,
        ),
      ),
    );
  }

  void _openMessages() {
    Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => const SupportScreen(),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<List<FarmPublicProfileRecord>>(
      future: widget.farmsFuture,
      builder: (context, farmsSnapshot) {
        final farms =
            farmsSnapshot.data ?? const <FarmPublicProfileRecord>[];
        final followedFarms = _followedFarms(farms);
        final farmUpdateRows = followedFarms.isNotEmpty
            ? followedFarms
            : farms;

        return RefreshIndicator(
          onRefresh: _refreshSocialHome,
          child: LayoutBuilder(
            builder: (context, constraints) {
              final showLeftRail = constraints.maxWidth >= 1080;
              final showRightRail = constraints.maxWidth >= 1210;

              return ListView(
                physics: const AlwaysScrollableScrollPhysics(),
                padding: EdgeInsets.zero,
                children: [
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      if (showLeftRail)
                        SizedBox(
                          width: 150,
                          child: _HpjSocialCommerceLeftRail(
                            cartItemCount: widget.cartItemCount,
                            onMyBox: widget.onMyBox,
                            onNutrition: _openNutrition,
                            onOrders: widget.onOrders,
                            onSaved: _openSaved,
                            onMessages: _openMessages,
                            onFarms: _openFollowedFarms,
                            onSettings: widget.onAccount,
                          ),
                        ),
                      Expanded(
                        child: Padding(
                          padding: EdgeInsets.fromLTRB(
                            showLeftRail ? 14 : 20,
                            12,
                            showRightRail ? 12 : 20,
                            32,
                          ),
                          child: Column(
                            crossAxisAlignment:
                                CrossAxisAlignment.start,
                            children: [
                              _HpjFarmStoriesStrip(
                                farms: farms,
                                products: widget.products,
                                followedFarmIds: followedFarmIds,
                                onFarm: _openFarm,
                                onProduct: widget.onOpenProduct,
                                onAddProduct: widget.onAddProduct,
                                onViewAll: _openFarms,
                              ),
                              const SizedBox(height: 10),
                              _HpjFollowFreshCard(
                                products: widget.products,
                                followedProductIds: followedProductIds,
                                followedCategories: followedCategories,
                                onToggleProduct: _toggleProductFollow,
                                onToggleCategory: _toggleCategoryFollow,
                              ),
                              const SizedBox(height: 10),
                              _HpjCommunityHomeFeed(
                                farms: farms,
                                products: widget.products,
                                followedFarmIds: followedFarmIds,
                                onOpenFarm: _openFarm,
                                onOpenReels: widget.onOpenReels,
                                onOpenProduct: widget.onOpenProduct,
                                onAddProduct: widget.onAddProduct,
                              ),
                              const SizedBox(height: 10),
                              const HpjHarvestDropPreview(
                                compact: true,
                              ),
                              const SizedBox(height: 10),
                              const HpjRescueHarvestPreview(
                                compact: true,
                              ),
                              const SizedBox(height: 10),
                              _HpjFreshPicksSocialRow(
                                products:
                                    _filteredFreshPickProducts.take(5).toList(),
                                selectedFilter: selectedFreshPickFilter,
                                onFilterSelected: (value) {
                                  setState(() {
                                    selectedFreshPickFilter = value;
                                  });
                                },
                                onShop: widget.onShop,
                                onOpenProduct: widget.onOpenProduct,
                                onAddProduct: widget.onAddProduct,
                                isFavorite: widget.isFavorite,
                                onToggleFavorite: widget.onToggleFavorite,
                              ),
                              const SizedBox(height: 10),
                              _HpjRecommendedCommerceRow(
                                products:
                                    _personalizedProducts.take(5).toList(),
                                onShop: widget.onShop,
                                onOpenProduct: widget.onOpenProduct,
                                onAddProduct: widget.onAddProduct,
                                isFavorite: widget.isFavorite,
                                onToggleFavorite: widget.onToggleFavorite,
                                signalForProduct: _productSignal,
                                signalColorForProduct: _productSignalColor,
                              ),
                              const SizedBox(height: 10),
                              _HpjFreshFarmUpdatesRow(
                                farms: farmUpdateRows,
                                showingFollowing:
                                    followedFarms.isNotEmpty,
                                onFarm: _openFarm,
                                onViewAll: followedFarms.isNotEmpty
                                    ? _openFollowedFarms
                                    : _openFarms,
                              ),
                            ],
                          ),
                        ),
                      ),
                      if (showRightRail)
                        SizedBox(
                          width: 276,
                          child: Padding(
                            padding: const EdgeInsets.fromLTRB(
                              0,
                              14,
                              14,
                              30,
                            ),
                            child: _HpjSocialCommerceRightRail(
                              customerNameFuture:
                                  widget.customerNameFuture,
                              cartItemCount: widget.cartItemCount,
                              savedCount:
                                  widget.favoriteProducts.length,
                              followedFarmCount:
                                  followedFarmIds.length,
                              trendingProducts:
                                  _trendingProducts.take(5).toList(),
                              favoriteProducts:
                                  widget.favoriteProducts,
                              recentlyViewedProducts:
                                  widget.recentlyViewedProducts,
                              onShop: widget.onShop,
                              onOpenProduct: widget.onOpenProduct,
                              onFarms: _openFarms,
                            ),
                          ),
                        ),
                    ],
                  ),
                ],
              );
            },
          ),
        );
      },
    );
  }
}


